SET LOCAL lock_timeout='4s';
LOCK TABLE private.authored_event_catalog IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.event_cases IN SHARE ROW EXCLUSIVE MODE;
DO $migration$
DECLARE n int;
BEGIN
 IF (SELECT count(*) FROM private.authored_event_catalog)<>330 OR EXISTS(SELECT 1 FROM private.authored_event_catalog WHERE content ? 'pre_decision_editorial_archive') THEN RAISE EXCEPTION 'Unexpected catalogue baseline'; END IF;
 CREATE TEMP TABLE gos_hint_patch ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset($gos_payload$[{"case_key":"bank-budget-bridge","old_hash":"fb3295e82504cd66c3de85d913243602","situation":"8 апреля 2024 года в Вязьме Смоленской области обрушился Панинский путепровод. По сообщению регионального МЧС на путепроводе находились автомобили; проводились аварийно-спасательные работы, нарушилось транспортное сообщение.\n\nДля расходов на восстановление требуется отдельное подтверждённое основание."},{"case_key":"bank-budget-health","old_hash":"c014183afd0a8fedc64e76c934761d9b","situation":"6 ноября 2025 года прокуратура Томской области сообщила о результатах проверки детской стоматологической поликлиники № 2 города Томска. Поводом стали публикации о трудностях получения медицинской помощи детьми. Проверка установила, что запись на плановый приём была доступна через портал «Госуслуги», регистратуру и телефон, однако записаться заранее фактически не удавалось: свободное время открывалось только на следующий день. Кроме того, учреждению не хватало врачей-стоматологов. Прокуратура внесла представление в региональный департамент здравоохранения.\n\nРешение принимается на условный момент выявления проблемы."},{"case_key":"bank-budget-school","old_hash":"b949511c0ff6e0b708b1171578e8a95f","situation":"24 сентября 2025 года прокуратура Железнодорожного района Самары сообщила о ситуации с кровлей школы № 37. По доступным материалам речь шла о протечках. В условиях задачи по техническому акту часть помещений признана опасной для занятий. Решение принимается на условный момент обнаружения протечек, до ремонта."},{"case_key":"bank-bus","old_hash":"56579898da8efeb6efc7c58178d326b4","situation":"10 марта 2023 года Генеральная прокуратура Российской Федерации сообщила об улучшении транспортного обслуживания населения Омской области. Поводом стало в том числе обращение жительницы посёлка Омский с населением около 4,3 тысячи человек, которой было трудно добираться до областного центра.\n\nВ условиях задачи перевозки организованы по регулируемым тарифам на основании государственного или муниципального контракта. Это не утверждение о тарифе и форме договора исторического маршрута. Решение принимается на условный момент выявления проблемы."},{"case_key":"bank-cat-mayor","old_hash":"2b0fb776c3286d6a4dc0373c9db9fc23","situation":"Кот из соседнего двора забрался в муниципальную приёмную и лёг на папку секретаря. Посетитель снял смешное видео и предложил пресс-службе опубликовать его от имени администрации. В кадре хорошо видны фамилия заявительницы, домашний адрес и номер её заявления о семейном конфликте. Журналист уже просит исходный файл, а секретарь считает сведения безобидными: посетитель всё равно сидел рядом. Приём граждан продолжается. У пресс-службы есть возможность закрыть документы и переснять короткий нейтральный эпизод.\n\nУ администрации нет самостоятельного основания для открытой публикации указанных персональных данных."},{"case_key":"bank-ceremony","old_hash":"73d6c2113bf35127940c561e620d3c7a","situation":"На открытии сквера церемониальные ножницы не перерезают ленту. Ведущая уже дважды попросила оркестр повторить вступление, дети ждут прохода к новой площадке, а подрядчик предлагает срочно купить дорогой режущий инструмент. Организатор держит запас обычных ножниц в хозяйственном помещении. По договору оплачена сама церемония, специальный инструмент в неё не включён. Представитель заказчика может согласовать изменение символического жеста без изменения программы и доступа в сквер. Пресс-служба просит закончить открытие вовремя, поскольку дальше выступает школьный ансамбль."},{"case_key":"bank-curated-light-01","old_hash":"f4790f5fd6481ad9bedf72494e418039","situation":"Детский совет научного центра выбрал талисман: аксолотля в огромных очках. Рисунок сделала участница кружка, но взрослый дизайнер принёс похожий вариант и просит сразу напечатать его на билетах. Его договор пока не подписан, а родители школьницы разрешали лишь показать работу на выставке. Директору нравятся оба рисунка, и он предлагает определить победителя на закрытом совещании. Педагог просит заранее объявить условия участия, способ выбора и разрешённое использование работ. На изготовление первой партии сувениров ещё есть месяц.\n\nУчебное условие: исключения свободного использования рисунков для тиража и переработки не применяются; возраст школьницы необходимо уточнить до оформления прав."},{"case_key":"bank-curated-light-02","old_hash":"b585e37fdfc149c1e810484914861513","situation":"Студенты предлагают устроить в библиотеке выставку устаревших справок, штампов и табличек «Обед». Среди экспонатов оказалась копия заявления о пособии с фамилией реального жителя и справка о его состоянии здоровья. Куратор хотел показать, сколько документов раньше приходилось собирать, а заместитель главы требует отменить выставку: посетители будут смеяться над администрацией. Библиотекарь предлагает обезличенные макеты и стенд, где объяснено, какие процедуры уже отменены и как получить услугу сейчас. До открытия три дня.\n\nУчебное условие: оригиналы позволяют идентифицировать граждан; основание для публичного раскрытия их медицинских сведений отсутствует."},{"case_key":"bank-curated-light-03","old_hash":"7f878bd40d5e3ceea2b1c9d29d78cc4e","situation":"Жители двух домов просят огороженную площадку для собак на пустыре рядом со школой. Учитель физкультуры показывает план: часть территории уже используется для занятий и прохода детей к стадиону. Владельцы собак предлагают приходить вечером и обещают сами убирать площадку. Земельный отдел ещё не проверил границы школьного участка, а подрядчик готов завтра поставить временный забор. На встречу пришли обе группы, каждая считает место общедоступным.\n\nГраницы школьного участка и допустимое место выгула не установлены."},{"case_key":"bank-curated-light-04","old_hash":"8a4a9d0e0b478bae5ae1c19c6d558b1d","situation":"Транспортное предприятие хочет пустить по выходным литературный автобус. Режиссёр предлагает заменить объявления остановок короткими стихами, а водитель опасается, что пассажиры не поймут, где выходить. Общество незрячих просит сохранить ясные названия остановок и сведения о пересадках. Поэт согласен бесплатно прочитать свои тексты, но звукозапись принадлежит студии, с которой ещё не договорились. В программе можно выделить отдельные паузы, не закрывая обязательную информацию. Руководитель просит подготовить пробный маршрут на месяц.\n\nУчебное условие: запись студии не опубликована в коммерческих целях; законного основания её публичного использования пока нет. Требуется организовать именно существующий пробный маршрут."},{"case_key":"bank-curated-light-05","old_hash":"9f99dc1e2071c29784344e7a960d6e46","situation":"Архитектор предлагает поставить на площади непрерывную скамью длиной почти во весь квартал. На картинке она выглядит как извилистая река, а смета на изготовление укладывается в выделенную сумму. Начальница службы благоустройства замечает, что секции перекрывают подъезд уборочной машины и доступ к двум люкам. Замена повреждённого участка потребует разбирать соседние элементы. В проекте пока нет расчёта ежегодного содержания. Мастерская готова изготовить одну разборную секцию и дать её для пробной установки. Жители хотят увидеть скамью к лету, но контракт на весь объект ещё не заключён."},{"case_key":"bank-curated-light-06","old_hash":"c5757fc0ecd88f53637976dd02d30100","situation":"Молодёжный совет придумал настольную игру о выдаче городских разрешений. Игрок тянет карточку, объясняет решение и получает фишки за понятный ответ. На пробной партии депутат обнаружил правило, которого уже нет в действующем регламенте. Сотрудник администрации предлагает раздать игру школам без исправлений: тираж небольшой, а мероприятие объявлено. Авторы готовы провести открытую встречу и записать вопросы жителей. Несколько участников хотят сразу передать конкретные жалобы на услуги.\n\nУчебное условие: несколько жалоб переданы уполномоченному сотруднику письменно с необходимыми реквизитами; для них действует порядок регистрации независимо от игровой встречи."},{"case_key":"bank-curated-light-07","old_hash":"e905947ce33cdd22dc8f81c4b4d5703a","situation":"Садовник нашёл на городской лужайке огромный гриб, и фотография быстро привлекла посетителей. Экскурсовод предлагает провести к нему дорожку и брать плату за фотографии. Биолог пока не определил вид и просит не трогать грибницу. Рядом проходит поливочная труба, а на газоне уже появились вытоптанные круги. Директор парка готов поставить переносную табличку и показать находку с существующей дорожки. В местной Красной книге вид ещё никто не проверял, поэтому называть его охраняемым оснований нет."},{"case_key":"bank-curated-light-08","old_hash":"4f4dff9bdeed62a6c019b84c5b5ef81c","situation":"На складе дома культуры нашли стулья от старых мероприятий: деревянные, металлические и один ярко-зелёный. Художница предлагает собрать из них временную уличную инсталляцию. Часть предметов числится в учёте учреждения, у нескольких расшатаны ножки. Автор хочет разрешить детям залезать на верхний ряд ради фотографий. Заведующий складом готов предоставить инвентарный список, а техник предлагает низкую композицию за ограждением, без использования мебели как оборудования для игры. Выставку хотят открыть в выходные и разобрать через неделю."},{"case_key":"bank-curated-light-09","old_hash":"5b2774cade72710de89a8816ad2f4632","situation":"Театральная студия готова сыграть сатиру об очередях прямо в холле центра услуг. Руководитель надеется снять напряжение, но в это же время назначен приём заявителей по предварительной записи. Декорации занимают проход к окну, а актёры хотят вовлекать ожидающих людей в сцену с вымышленными отказами. Посетительница уже спросила, будет ли её настоящий талон действовать после спектакля. Администратор может предоставить зал после завершения приёма и сохранить форму обратной связи для желающих.\n\nСъёмка посетителей не предполагается."},{"case_key":"bank-curated-light-10","old_hash":"97104fac0a905ba4fbbb37d4cafd33a6","situation":"Типография доставила кружки для городского праздника, и на каждой герб напечатан вверх ногами. В техническом задании приложено правильное изображение, а часть партии уже собираются передать как официальные подарки. Производитель признаёт ошибку и готов заменить тираж за свой счёт. Дизайнер предлагает продать брак как коллекционную шутку, но учреждение не проверило местный порядок использования символа и полномочия на продажу имущества. До церемонии два дня, поэтому можно получить небольшую исправленную партию в первую очередь.\n\nУчебное условие: закупка проведена по 44-ФЗ; несоответствие герба не устранено, отдельного законного основания принять дефектную партию нет."},{"case_key":"bank-curated-light-11","old_hash":"4ecc6388db2a0472950eb9502746ba6a","situation":"Уличная труппа просит показать короткие пьесы на автобусных остановках. Режиссёр выбрал широкую площадку у перекрёстка, но утром там выстраивается очередь на пригородный рейс. Представитель перевозчика опасается, что зрители перекроют посадку, а звук заглушит объявления. Возле соседней библиотеки есть свободная площадка в стороне от проезжей части; её управляющий готов обсудить время. Политических требований или шествия труппа не заявляет. Отдел культуры предлагает сразу потребовать процедуру публичного митинга, не выяснив характера мероприятия. В учебном условии цель — исключительно показ пьес; не заявлено коллективное выражение или формирование мнений либо требований по вопросам общественной жизни."},{"case_key":"bank-curated-light-12","old_hash":"d6ff4bc1bd414b58409cb0f9c61661e3","situation":"Соседский хор репетирует во дворе многоэтажного дома. Руководитель приносит колонку, а участники постепенно остаются петь всё дольше. Молодые родители жалуются, что вечером не могут уложить ребёнка, и показывают запись громкой репетиции. Певцы отвечают, что культура должна быть доступна всем, и предлагают просто закрывать окна. Библиотека может выделить помещение два раза в неделю, а на выходных хор готов петь без усилителя днём. Участковый просит учитывать действующий в регионе режим тишины, не называя универсальных для всей страны часов."},{"case_key":"bank-curated-light-13","old_hash":"aea69d177d26242f2ebf37505595557a","situation":"Новый пешеходный мостик готовят к окраске. Архитектор предложил три оттенка защитного покрытия, каждый совместим с материалом и утверждённым проектом. В городском опросе неожиданно лидирует вариант «прозрачный мост», добавленный шутником в свободное поле. Подрядчик уже просит окончательный ответ, чтобы заказать материалы. В контракте разрешён выбор оттенка заказчиком, но не изменение системы защиты металла. Дизайнер хочет объявить шуточный ответ обязательным результатом волеизъявления. Жители, напротив, ждут нормального понятного выбора."},{"case_key":"bank-curated-light-14","old_hash":"0758419cc6ac76e53e83cc3217e12cf8","situation":"На день города школьники хотят заложить капсулу с письмами, которую откроют через двадцать лет. Строители предлагают спрятать её под плиткой новой площади, но схема закладки не подготовлена. В письмах дети указали домашние адреса и семейные истории. Музей готов принять коробку на хранение, составить опись и предусмотреть передачу ответственности следующему хранителю. Родители спрашивают, будут ли письма доступны посетителям до назначенного срока. Инициаторы уже запечатали часть конвертов, не согласовав правила раскрытия.\n\nУчебное условие: самостоятельного правового основания для открытой публикации адресов и частных писем нет; условия будущего доступа подлежат отдельной проверке."},{"case_key":"bank-curated-serious-01","old_hash":"06f24605caff133faa4530d6a0b24222","situation":"Утром реестр обращений перестал открываться. На экране появилось требование выкупа. Вчера сотрудники приняли двадцать заявлений; последняя проверенная резервная копия сделана три дня назад. В журнале приёмной сохранились регистрационные номера, а часть документов есть в защищённой почтовой системе. Специалист просит не перезагружать заражённый сервер, пока не сохранены следы инцидента. Руководителю нужно восстановить приём граждан и выяснить, были ли раскрыты персональные данные. Обычные сроки рассмотрения обращений продолжают идти.\n\nОрган является оператором персональных данных. Сроки рассмотрения обращений сохраняются."},{"case_key":"bank-curated-serious-02","old_hash":"f2f26578642301d879d0bb7da70d4fae","situation":"8 августа 2024 года прокуратура Центрального района Сочи сообщила об устранении аварийной ситуации возле улицы Цюрупы. Оползневые процессы сместили грунт и повредили коллектор. Комиссионное обследование выявило перелом участка и изношенные колодцы: выходившая вода подмывала фундамент многоквартирного дома. Риск затронул одновременно инженерную сеть, склон и жильё. Причины, не указанные в сообщении прокуратуры, остаются неподтверждёнными.\n\nУчебное продолжение исторического сообщения прокуратуры о ремонте коллектора; сообщение не подтверждает нынешнее состояние дома и склона. Владелец сети, управляющая организация и компетентные органы установлены для учебной модели; временное размещение только при наличии оснований."},{"case_key":"bank-curated-serious-03","old_hash":"9fcf6cc2136009aafffeca4d59d51594","situation":"30 апреля 2025 года прокуратура Краснодара сообщила о проверке доступности подземного перехода через улицу Красных Партизан рядом с Краевой клинической больницей №2. Необходимые информационные знаки отсутствовали, а подъёмной платформой можно было воспользоваться только после прибытия сопровождающего. Оценке подлежат подходы, навигация, исправность платформы и возможность своевременно получить помощь сопровождающего.\n\nИсторическое сообщение касается выявленных и впоследствии устранённых нарушений. Нынешнее нарушение не утверждается; дальнейшее улучшение маршрута моделируется учебно."},{"case_key":"bank-curated-serious-04","old_hash":"5f571e21488e6b1cd1666c195178a63f","situation":"Социальная служба принимает женщину с ребёнком после угроз дома. Возвращаться по прежнему адресу они боятся. В защищённом отделении осталось одно семейное место, а ещё два можно открыть после согласования с другим поставщиком услуг. Документы на обычное социальное обслуживание ещё не собраны. Волонтёр предлагает опубликовать адрес размещения, чтобы быстрее найти вещи и продукты; сотрудница предупреждает о риске обнаружения семьи человеком, от которого поступают угрозы. Полиция и медицинская помощь доступны по отдельным каналам.\n\nУчебное условие: имеются сведения о потребности в срочных социальных услугах и возможность организовать защищённое размещение; основание для распространения адреса отсутствует."},{"case_key":"bank-curated-serious-05","old_hash":"30f1116f13711acc6474af81db38c47b","situation":"На трёх фермах ветеринарная лаборатория выявила заразную болезнь животных. Главный ветеринарный специалист подготовил предложение об ограничительных мерах. Владельцы согласны временно не вывозить животных, но требуют понятных границ карантина и объяснения условий возмещения, если потребуется изъятие. Один фермер опасается, что соседи узнают сведения раньше официального уведомления. Администрация не вправе самостоятельно назначать диагноз или обещать любую запрошенную сумму."},{"case_key":"bank-curated-serious-06","old_hash":"fb5e6705c5c7fe0c8847762c7b6362d5","situation":"11 ноября 2025 года прокуратура Первомайского района Владивостока сообщила о проверке аварии на подстанции «Улисс». По первоначальному сообщению ведомства, без электричества остались более двадцати тысяч жителей; в перечне затронутых социальных объектов указаны четыре детских сада и две школы. Ведомство взяло восстановление снабжения на контроль. Причина аварии и виновные в этой публикации не установлены."},{"case_key":"bank-curated-serious-07","old_hash":"d3ba473e381ca0dcd12ddebfaeb315d1","situation":"После прорыва трубы вода попала в хранилище городского архива. Намокли дела о строительстве старых домов и документы по личному составу. Здание можно ремонтировать, но подрядчик просит освободить помещение за сутки и предлагает сложить коробки в гараже. Архивист видит риск смешать описи и потерять листы, а реставратор готов сначала отделить наиболее повреждённые единицы и определить режим сушки. Часть материалов содержит персональные сведения, поэтому открытая волонтёрская сортировка подходит не для всех документов."},{"case_key":"bank-curated-serious-08","old_hash":"9ce6a7fcd6db2cca28adc1db428f9f93","situation":"После ввода небольшой дамбы жители перестали видеть рыбу на привычном нерестовом участке. У владельца сооружения есть разрешённый режим эксплуатации, но экологическая служба просит проверить, достаточно ли воды поступает ниже по течению. Энергетики предупреждают о потере выработки при изменении сброса. Их журнал показывает расход воды только у турбины, а наблюдения рыбаков пока не подтверждены исследованием.\n\nВодопользование и режим эксплуатации разрешены в заданных пределах."},{"case_key":"bank-curated-serious-09","old_hash":"36b2134e6faac5591d29179b1485a649","situation":"На закупку школьной формы поступили три заявки с почти одинаковыми ценами. В двух файлах повторяется редкая опечатка, хотя поставщики заявлены как независимые. Антимонопольный орган запросил оригиналы документов и сведения об обмене сообщениями на площадке. Заказчик должен сохранить материалы, а родители опасаются задержки поставки к учебному году. Общность цены ещё не доказывает сговор: она может объясняться одним производителем ткани или иной причиной.\n\nУчебное условие: требование антимонопольного органа мотивировано, срок установлен, запрошены оригиналы и доступные материалы. Заказчик обязан его исполнить."},{"case_key":"bank-curated-serious-10","old_hash":"5ad955117c0d393da85cd8b810593bdb","situation":"Спортивная школа ждёт средства на оборудование секции. В отчёте распорядителя грант уже указан как использованный, однако на лицевом счёте школы поступления нет. Казначейская выписка, заявка школы и ведомственный реестр показывают разные стадии операции. Бухгалтер допускает, что плановое назначение по ошибке перенесли в колонку фактического расхода; директор подозревает перечисление другому получателю. Ни одна версия пока не доказана.\n\nРассматривается расход бюджета распорядителя."},{"case_key":"bank-curated-serious-11","old_hash":"55be8f80f18ff0fabf8db6ad4a812604","situation":"В школе пересматривают образовательную программу и расписание внеурочных занятий. Совет старшеклассников собрал предложения: сохранить лабораторные практикумы, изменить время кружков и добавить проектную неделю. Директор готов выслушать ребят, но опасается превратить педагогический совет в спор без решения. В уставе уже предусмотрен совет обучающихся, однако порядок передачи его предложений описан неясно. Представитель родителей просит заранее сообщить, какие вопросы могут решать сами ученики, а какие относятся к компетенции педагогов и руководителя.\n\nУстав школы предусматривает совет обучающихся."},{"case_key":"bank-curated-serious-12","old_hash":"e16b45b55cbb8c9cbae80f7e76f41aaf","situation":"После землетрясения иностранные власти запросили у России мобильный госпиталь. Региональная больница располагает выездным оборудованием, но часть специалистов дежурит в местном травматологическом центре. Федеральный координатор просит сведения о реально доступных ресурсах, а губернатор хочет объявить помощь немедленно. Руководитель больницы может выделить часть комплекта и резервную бригаду после подтверждения замены; самостоятельно оформлять международную миссию он не уполномочен. Масштаб внешней помощи пока не согласован.\n\nФедеральный координатор установлен условиями задачи; решение о международной миссии ещё не принято."},{"case_key":"bank-curated-serious-13","old_hash":"8158fe79d9ad958cc9edd60ee62eb218","situation":"В центр временного размещения прибыли семьи после пожара в соседнем регионе. Часть людей потеряла паспорта и медицинские документы. У одного ребёнка высокая температура; отец другой семьи спрашивает, как продолжить школьное обучение. Волонтёры предлагают свободные комнаты, но администрация ещё не проверила безопасность размещения и не определила ответственного за сопровождение. Уполномоченные службы могут начать восстановление документов параллельно с срочной помощью.\n\nУчебное условие: нуждаемость семей в срочных социальных услугах установлена, получено заявление или предусмотренная законом информация; доступно безопасное временное размещение."},{"case_key":"bank-curated-serious-14","old_hash":"1d2854e1561be0374c1742eb71ab789b","situation":"Компания предлагает открыть карьер возле границы заповедника. В презентации указаны новые рабочие места, но схема водоотвода пока не показывает, куда попадут стоки при сильном дожде. Предприятие находится вне обозначенной на его карте территории заповедника; эколог напоминает, что нужно проверить ещё охранную зону и связь водоносных горизонтов. Проект не получил всех необходимых разрешений. Жители хотят понять, можно ли обсуждать гарантии занятости до проверки природоохранных ограничений.\n\nПроект ещё не имеет обязательных разрешений."},{"case_key":"bank-curated-serious-15","old_hash":"af288ece01c586f4b8af89cde4803dd2","situation":"Инициативная группа предлагает местный референдум о транспортной реформе. В одном вопросе соединены изменение маршрутов, снижение тарифа и обязательное увеличение бюджетных расходов. Часть подписавшихся поддерживала только новый маршрут к поликлинике. Комиссия просит уточнить правовые последствия ответа «да», а активисты считают любое замечание отказом от участия граждан. Решение о назначении ещё не принято.\n\nВопрос местного референдума объединяет самостоятельные решения и обязательное увеличение бюджетных расходов."},{"case_key":"bank-curated-serious-16","old_hash":"6a637c692328d08724a289b30ac02722","situation":"Лесная служба предлагает искать ранние очаги пожара с беспилотников. Пробный маршрут проходит над лесной опушкой и частными участками: на записи различимы люди и номера машин. Подрядчик хочет хранить всё видео бессрочно, чтобы обучать собственную программу распознавания. Руководитель службы располагает планом лесной охраны, но согласование полётов и правила доступа к записям ещё не оформлены. Жители готовы поддержать наблюдение за дымом, если понимают его границы.\n\nЗаписи позволяют идентифицировать людей и транспорт; законное основание для бессрочного стороннего использования и съёмки лишних участков не установлено."},{"case_key":"bank-curated-serious-17","old_hash":"9cd8333b84a42e55f5c943cf772480be","situation":"Родители сельской школы подали заявления об изучении родного языка. Желающих достаточно для небольшой группы, но единственный местный педагог ведёт полную нагрузку. Университет предлагает занятия с преподавателем по видеосвязи и методическую поддержку учителю на месте. У школы есть свободный кабинет и оборудование; нужно уточнить программу, квалификацию и расписание. Часть родителей опасается, что новый факультатив сделают обязательным для всех или сократят занятия русским языком.\n\nЗанятия предполагаются в добровольной группе."},{"case_key":"bank-curated-serious-18","old_hash":"8f25046987d9f3c501dd6b38baf3c91d","situation":"20 марта 2025 года прокуратура Благовещенска сообщила о состоянии участка дороги от улицы Богдана Хмельницкого до строения №99/1. Прокуратура сообщила о затруднённом проезде, в том числе транспорта спецслужб. Суд удовлетворил требования об очистке участка от снега и наледи и профилировании проезжей части в течение месяца после вступления решения в силу. На дату публикации решение ещё не вступило в силу; выполнение работ не подтверждено.\n\nУчебная постановка: неудовлетворительное состояние участка затрудняет проезд спецслужб."},{"case_key":"bank-curated-serious-19","old_hash":"4f24cd7fa3020b174f4176fb6df52952","situation":"Район не может привлечь врачей и учителей: стоимость съёма жилья заметно выросла. В муниципальном фонде есть несколько служебных квартир, а собственники ещё десяти готовы обсуждать аренду по программе. Отдел кадров предлагает раздавать помощь по письму руководителя учреждения; жилищная служба просит установить критерии, срок и основания прекращения поддержки. Одни кандидаты уже имеют пригодное жильё рядом с работой, другие ездят издалека.\n\nВ условиях задачи существуют служебный жилищный фонд и возможность договорной аренды; бюджетное обязательство заранее не предполагается."},{"case_key":"bank-curated-serious-20","old_hash":"3d89afd551a85fffeca49174837cb61e","situation":"В городских чатах появился файл с гербом администрации: жителей призывают немедленно покинуть дома из-за якобы разрушенного водопровода. Диспетчер водоканала аварии не подтверждает, а официальный канал молчит уже час. Несколько семей начали собирать вещи. Пресс-служба получила исходный файл и может связаться с дежурными службами; полиция просит сохранить сведения о распространении."},{"case_key":"bank-curated-serious-21","old_hash":"212ee60c3b63c496ff039146d484b547","situation":"В жаркий выходной на официальном пляже стало вдвое больше отдыхающих, чем обычно. Двое спасателей заболели, а руководитель станции располагает только частью подготовленной смены. Осмотр выявил участок с опасным течением; на соседней мелководной зоне угрозы и возможности наблюдения отличаются. Организатор концерта просит не менять режим пляжа ради уже проданных билетов. Компетентная служба может привлечь резерв после проверки подготовки людей, но не вправе заменить спасателей случайными волонтёрами. Ограничения вводит ответственное за использование пляжа лицо в пределах компетенции; открытая часть пляжа используется только при обеспечении обязательных требований безопасности."},{"case_key":"bank-curated-serious-22","old_hash":"1372cefe71eadb2bc72c541d65d8b7d4","situation":"За день до государственной итоговой аттестации в студенческом чате появился файл, похожий на закрытые задания. Один преподаватель узнаёт старые формулировки, другой отмечает несоответствие действующему комплекту. Уполномоченный организатор может проверить происхождение файла и использовать предусмотренный процедурой резерв, если компрометация подтвердится. Студенты опасаются, что их обвинят в нарушении только за получение пересылки. Секретарь предлагает немедленно объявить пересдачу всем, хотя ни подлинность файла, ни доступ конкретных участников ещё не установлены."},{"case_key":"bank-curated-serious-23","old_hash":"d734a7c08e712c6239b6f6a476e2547d","situation":"27 апреля 2026 года Генеральная прокуратура сообщила о защите прав детей на охрану здоровья. В опубликованном случае жительница Дагестана жаловалась на постоянные перебои с лекарствами и медицинскими изделиями для сына с сахарным диабетом. Прокуратура внесла представление региональному министру здравоохранения. Решение принимается на условный момент выявления проблемы."},{"case_key":"bank-curated-serious-24","old_hash":"7d11640047f0a9d624238efdf83a32d3","situation":"Экскаватор при расширении дороги открыл слой с керамикой и остатками старой кладки. Рабочие остановили ковш, но руководитель подрядчика просит продолжить рядом, чтобы не нарушить календарь. Приглашённый археолог считает признаки существенными; официального решения о статусе находки пока нет. На плане можно обозначить затронутый участок, а движение временно сохранить по другой полосе после проверки безопасности.\n\nУчебное условие: соседние земляные работы также затрагивают зону возможной находки; исключений из обязанности приостановить работы нет."},{"case_key":"bank-curated-v2-01","old_hash":"253376770c8c157e723e60f615b17c87","situation":"В 05:40 на речной переправе оборвался трос. Посёлок Левобережный оказался отрезан от районной больницы; объезд занимает четыре часа. Дежурный врач назначил двум пациентам доставку в ближайший час. У спасателей есть проверенный катер и топливо на два рейса, подвоз запаса возможен через сорок минут. Предприниматель предлагает понтон, но его осмотр займёт минимум половину дня. В местном медпункте нет оборудования для назначенной помощи. Наличие ещё одного плавсредства не означает, что его можно считать безопасной готовой переправой."},{"case_key":"bank-curated-v2-02","old_hash":"467d7b7deacecd22ef8285e030b5cb84","situation":"Провизор Олег принимает вакцины для выездной бригады и замечает сорокаминутный разрыв в температурном журнале. Коробки холодные, однако непрерывность условий перевозки документально не подтверждена. Поставщик просит подписать приёмку сейчас и обещает прислать сведения вечером. В соседнем районе есть проверенная партия, доставку которой можно согласовать без нарушения её собственного температурного режима. Завтра запланирован приём в отдалённом посёлке."},{"case_key":"bank-curated-v2-03","old_hash":"f89f022add40360da5ae72dc87c15bc4","situation":"Уборщица Вера увидела в табеле, что её ночные смены записаны как дневные. Такая же ошибка появилась у двадцати работников после переноса данных. В бумажном журнале проходов сохранились часы, а руководитель смены готов подтвердить расписание. До выплаты зарплаты два дня. Директор предлагает исправить всё в конце квартала, чтобы сейчас не менять отчётность. Бухгалтер может сверить записи до формирования ведомости и сохранить историю корректировки.\n\nУчебное условие: фактические ночные часы подлежат установлению по совокупности достоверных сведений; ближайший срок выплаты наступает до предложенной отсрочки."},{"case_key":"bank-curated-v2-04","old_hash":"914eebcb4078b9c5747d26a17d53edb1","situation":"В аппарат совета пришло анонимное письмо: автор утверждает, что спортивную площадку продают под склад. К письму приложена фотография чертежа без даты. В открытом реестре есть два участка с похожими номерами; один относится к площадке, другой к соседней территории. До заседания три часа, и дежурный специалист может проверить обе записи. Тренер уже собирает родителей, а собственник соседнего участка опасается необоснованных обвинений.\n\nУчебное условие: получено бумажное письмо без фамилии и почтового адреса; данных о конкретном противоправном деянии и совершившем его лице пока нет."},{"case_key":"bank-curated-v2-05","old_hash":"5bb8e441a45268c2db8de0cd28282224","situation":"Мастер Лев нашёл трещину в резервном насосе котельной. Основной насос работает, но в выходные ожидается похолодание. Инженер подтвердил возможность четырёхчасового ремонта своей бригадой в период пониженной нагрузки. Для соседнего стационара есть проверенные временные источники тепла; их установку и безопасный режим нужно заранее согласовать с ответственным медицинским работником. Новая деталь прибудет в понедельник и относится уже к дальнейшему восстановлению."},{"case_key":"bank-curated-v2-06","old_hash":"89a68e942349b9a5e66f5213ee7f7606","situation":"Пенсионерка Нина третий раз приходит за назначенной компенсацией проезда. Одна запись в связанной системе ошибочно помечает её умершей, хотя паспорт действителен и решение о выплате сохранилось. Техническое исправление займёт три дня; платёжный реестр формируется сегодня. В учебном регламенте для такой подтверждённой ошибки обязательна служебная ручная проверка с документированием основания до формирования реестра. Разработчик предлагает временно отключить проверку статуса для всех заявителей, но это создаст риск необоснованных выплат.\n\nПраво на компенсацию и обязанность ручной проверки установлены учебным регламентом."},{"case_key":"bank-curated-v2-07","old_hash":"a2e87b3e7498201f5900ed0257661960","situation":"В центре временной помощи заболел переводчик. Несколько семей не понимают условия размещения и боятся подписывать документы с незнакомыми словами. Проверенный специалист университета доступен сегодня до шестнадцати часов, а на следующие дни можно согласовать защищённый дистанционный перевод. Волонтёр предлагает загрузить фотографии всех паспортов и анкет в бесплатный публичный сервис. Документы содержат сведения о детях и здоровье. Необходимая срочная помощь может оказываться отдельно от планового оформления дальнейших услуг.\n\nУчебное условие: сведения о нуждаемости в срочной помощи получены; доступен проверенный способ коммуникации с ограниченным законным доступом к необходимым сведениям."},{"case_key":"bank-curated-v2-08","old_hash":"4933397d45881dbd7ec95bc074db4fde","situation":"Инженер Ася сравнила два ночных замера и заметила необычный расход воды в квартале. Районный счётчик недавно прошёл поверку. Школьный сторож сообщил о сыром подвале, но причина ещё не установлена. Специалист может обследовать конкретный участок до утреннего пика; аварийная бригада занята и просит точную заявку. Поиск и ремонт могут потребовать короткого отключения нескольких домов. Руководитель предлагает сразу заменить все счётчики, хотя такой закупки нет в бюджете."},{"case_key":"bank-curated-v2-09","old_hash":"3559b2c22e492bcb6329c55975ed1afe","situation":"На одном муниципальном участке предлагают детский сад и центр дневного пребывания пожилых. Две инициативные группы уверены, что землю уже обещали каждой из них, хотя договор не заключён. Архитектор рассматривает совместное здание, но его стоимость и санитарные требования ещё не проверены. Есть резервная площадка с худшей транспортной доступностью. Совет получил данные об очереди в сад, потребностях пожилых жителей и стоимости содержания вариантов. Подписи одной группы не заменяют правового основания передачи участка и не позволяют игнорировать другую подтверждённую потребность."},{"case_key":"bank-curated-v2-10","old_hash":"90bfe93d784c57d7b7eb0434000dc310","situation":"Во время учебной проверки диспетчер Илья получил отчёт: все сирены включились. Жители нового микрорайона в низине сигнала не услышали, а уведомление в приложении пришло после окончания тренировки. У части домов нет устойчивой мобильной связи. Подрядчик показывает зелёные индикаторы питания, совет дома предъявляет записи с балконов. Перенос сирены потребует нескольких дней; дежурный экипаж с громкоговорителем доступен в текущую смену. Зелёные индикаторы в диспетчерской показывают питание устройств, но не слышимость сигнала в домах. Любое изменение оборудования предполагает техническое согласование и соблюдение требований безопасности."},{"case_key":"bank-curated-v2-11","old_hash":"a8c3c41812519fece46778d69ddb38d2","situation":"Посёлок получил средства на восстановление первого этажа старого кинотеатра. Молодёжный клуб просит репетиционный зал. Кооператив хочет разместить мастерскую с учебными местами. Оба готовы пользоваться помещением в разные часы и не претендуют на исключительное владение всем зданием. Рабочий проектор позволяет сохранить ещё и небольшие кинопоказы. До подачи сметы пять дней. Месячный пробный календарь можно согласовать с уполномоченным владельцем в пределах назначения помещения; передача всего здания одному оператору требует отдельного решения. Само наличие гранта не позволяет обещать каждому полный ремонт или распоряжаться зданием вне установленного режима. Пробный календарь предполагает занятия под управлением учреждения без самостоятельной передачи проектам права владения или пользования помещением; при такой передаче требуется отдельная проверка основания."},{"case_key":"bank-curated-v2-12","old_hash":"f137e9400fe79964e0087f836b791bf7","situation":"Перед последним рейсом диспетчер просит Сергея выйти ещё раз. Учёт смен показывает, что допустимый режим именно этого водителя будет превышен; сам Сергей сообщает об усталости. Отмена рейса оставит торговцев без связи с посёлками до следующего дня. Через сорок минут доступен сменный водитель, а частный перевозчик предлагает исправный автобус с документами для проверки допуска. Пассажиров можно известить о задержке. Доплата или согласие водителя не отменяют установленных ограничений рабочего режима; выбранная подмена тоже требует проверки, а не доверия одному телефонному обещанию.\n\nУчебное условие: даже сокращённый рейс приведёт к превышению допустимого режима; законного исключения в описанной ситуации нет."},{"case_key":"bank-curated-v2-13","old_hash":"c62d09d4250b239e1c3632f66d432a01","situation":"Школьный кружок установил датчик воздуха у окна класса. В отдельные утра прибор показывает скачки, которых нет на станции за городом. Учительница Рита сохранила время, место и исходные показания; родители требуют немедленно остановить ближайший завод. Поверенная мобильная лаборатория готова приехать в течение часа и наблюдать неделю. В школе есть свободные помещения для временного изменения занятий по оценке ответственных лиц. Причина расхождения пока не установлена: это может быть локальный источник или особенность измерений."},{"case_key":"bank-curated-v2-14","old_hash":"e3518b0c728861f7e7c1638325db07aa","situation":"На портале общественного обсуждения транспортного плана перестали проходить ответы из сельских библиотек. Горожане продолжают участвовать, и экран показывает лидерство одного проекта. Координатор Лада сохранила бумажные предложения сельских жителей. Объявленный порядок допускает равноценный очный канал, итог ещё не подведён. Есть единый список участников, позволяющий исключить повторный учёт. Это консультация по плану, а не предусмотренные избирательным законом выборы или референдум. Бумажные предложения нельзя ни отбросить только из-за формата, ни прибавить без проверки происхождения и повторов.\n\nВ учебной модели проводится консультативный муниципальный опрос по статье 46 закона № 33-ФЗ при применимом региональном и местном порядке. Допускаются очный и дистанционный каналы; изменение срока или порядка утверждает компетентный представительный орган с соблюдением правил уведомления и равных возможностей. Идентификация и защита данных необходимы для исключения повторного учёта; результат рекомендательный."},{"case_key":"bank-curated-v2-15","old_hash":"76a71f108beeddd6decc0e55b6462a75","situation":"Ночной снег перекрыл подъезд к дому культуры, где назначено обсуждение материалов оценки воздействия нового карьера. Компания прибыла вовремя, жители двух улиц не могут добраться. В соседней школе есть доступный тёплый зал, однако первоначальное извещение указывает другое место. Несколько человек уже направили письменные замечания. Секретарь хочет провести встречу по прежнему календарю и считать отсутствие остальных отказом участвовать. Удобное помещение само по себе не позволяет менять юридически значимые условия процедуры без надлежащего оформления и информации для всех заинтересованных."},{"case_key":"bank-curated-v2-16","old_hash":"abb61f055f3f986bb50a11b8957446c8","situation":"Инга проверяет резерв для пунктов временного размещения. Несколько коробок с продуктами имеют истёкший срок годности, хотя в отчёте запас считается полностью пригодным. Спорные позиции уже отделены от остального остатка. Поставщик готов обменять часть по договору; соседний район может передать пригодный запас после согласования. Для ближайшей выдачи пригодных продуктов достаточно при адресном распределении. Закупщик предлагает дождаться новой партии и пока не менять отчёт. Замена этикетки не продлевает срок годности, а обещание поставки не является уже имеющимся запасом."},{"case_key":"bank-curated-v2-17","old_hash":"dbfdf73d438b70baf20d85412c90284e","situation":"Инвестор предлагает вычислительный центр и новые рабочие места. Для охлаждения запланирован водозабор из источника, которым пользуются жители и тепличный кооператив. Летом уровень воды уже снижался. Гидролог Павел просит сезонные данные, компания ждёт предварительного ответа за две недели. В проекте есть более дорогой замкнутый контур, значительно сокращающий потребление. Объёмы существующих пользователей известны, технические и разрешительные условия нового потребителя ещё не согласованы. Предварительное одобрение экономической идеи не должно выдаваться за оформленное право на любое количество воды независимо от сезонного дефицита.\n\nУточнение учебного условия: рассматривается поверхностный водный объект, а не подземный источник или подключение к коммунальной сети."},{"case_key":"bank-curated-v2-18","old_hash":"ee083ff1548cea2bd8251e5c35d69e67","situation":"Социальная пекарня обучает молодых людей с инвалидностью. Аренда муниципального помещения заканчивается через месяц; другое предприятие предлагает больший платёж и хочет открыть магазин. Руководитель Тамара просит продление без торгов, ссылаясь на уже набранную группу. Документы о текущем договоре и программе обучения доступны, но основание исключения из конкурентной процедуры ещё не проверено. Владелец готов обсуждать поддержку в пределах полномочий. Ни высокая цена магазина, ни полезность пекарни сами по себе не заменяют установленного решения о распоряжении публичным помещением."},{"case_key":"bank-curated-v2-19","old_hash":"c7ec73fddbe38c2d6a4e9769f6f1c2dd","situation":"Монтажник Тимур установил оборудование сельского интернета. На центральной площадке сигнал есть, но холм закрывает дома одной из трёх предусмотренных деревень. Учитель принёс расписание дистанционных занятий, которые там пока недоступны. Оператор может проверить адреса сегодня и рассматривает перестановку оборудования без полной новой стройки; отдельные согласования всё равно нужно оформить. Завтра назначена приёмка, от подтверждённого охвата зависит оплата. Глава района просит показать подключение всех деревень уже в сегодняшнем отчёте. Условия допускают запуск работающих точек, однако обязательство по домам за холмом пока не исполнено."},{"case_key":"bank-curated-v2-20","old_hash":"10e61c0223f93179b54694def53fdb83","situation":"Город-побратим предлагает подарить муниципалитету электрический автобус для экскурсий. За покупку платить не нужно, но механик Зоя установила близкую замену батареи. Гарантия её не покрывает; сервисный партнёр работает в другом регионе, а собственных подготовленных специалистов нет. Делегация готова обсудить обучение персонала. Транспортная служба располагает сопоставимым расчётом обычного автобуса и источников содержания. До подписания соглашения день, церемония уже объявлена. В расходы на перевозку детей войдут обслуживание и батарея. Объявленная церемония не подтверждает технической готовности автобуса."},{"case_key":"bank-curated-v2-21","old_hash":"8cfa87635e6770a24d560c33a77e02d2","situation":"Руководитель дорожного центра предлагает главным показателем сумму штрафов. Аналитик Дина сопоставила карту аварий и обращения: три опасных перекрёстка почти не совпадают с местами наибольшего числа взысканий. На спокойной улице водители жалуются на плохо заметный знак. Одна инспекторская группа может обследовать один участок за смену; владелец дороги готов проверить размещение знака. Бюджетное совещание завтра. При оценке нельзя превращать ожидание доходов в доказательство нарушения конкретного водителя или заставлять орган заранее выдавать нужное число постановлений независимо от установленных обстоятельств."},{"case_key":"bank-curated-v2-22","old_hash":"16525cfcea0be45201c0c3fb037df60b","situation":"Алина не попала в предварительный список муниципальной стипендии: программа подставила её прежний адрес. Учебное заведение подтвердило статус и другие предусмотренные основания, а корректное адресное сведение можно получить сегодня. Комиссия нашла несколько похожих ошибок; приказ о выплате ещё не издан. Порядок допускает исправление подтверждённых технических данных до окончательного решения. Секретарь предлагает исправить только письмо Алины, потому что она первая пожаловалась. Исправление записи не должно становиться скрытым добавлением нового основания стипендии для выбранного человека."},{"case_key":"bank-curated-v2-23","old_hash":"fa9c73bac094447828ad2d8ed2116519","situation":"После снегопада жители заселённого квартала чистят пешеходную дорогу к остановке сами. Диспетчер считает контракт выполненным: техника прошла все указанные улицы. На планшете водителя новой улицы действительно нет, хотя она уже принята в публичное содержание. У подрядчика есть свободное двухчасовое окно; законность дополнительного задания и оплаты нужно проверить отдельно. Дорожка стала скользкой, а расследование причины ошибки перечня займёт время. Факт наличия свободной машины не позволяет оплачивать любой не предусмотренный договором объём без оформления."},{"case_key":"bank-curated-v2-24","old_hash":"8bca6b3f8c16ab26a566919527817945","situation":"Район закупил мобильную библиотеку, но поставщик доставил только полки и книги. Специальный автобус задерживается; в восьми сёлах уже вывешены афиши. Книги занимают помещение кружка. Библиотекарь Мила предлагает временный выезд на другом микроавтобусе, использование которого нужно согласовать с владельцем и проверить по требованиям перевозки. Контрактный управляющий не может подписать акт полной поставки без автобуса. Спрос читателей подтверждён записями, а покупка ещё одного транспорта не обеспечена. Временный выезд не должен превращаться в скрытую приёмку неполного обязательства или отмену обязательных школьных рейсов."},{"case_key":"bank-curated-v2-25","old_hash":"e4d8396bc4aaacd45c3c309a7fce88fb","situation":"В центре социальной поддержки новый терминал и старая стойка выдают независимые номера. На двух экранах разное время, посетители спорят, кто пришёл раньше. Журнал фактической регистрации сохранён, сотрудник может восстановить единую последовательность в текущую смену. Руководитель Егор предлагает убрать бумажные талоны сразу, хотя часть пожилых людей нуждается в помощи при записи. Повторная регистрация заставит некоторых приехать ещё раз. Способ получения талона сам по себе преимущества не даёт.\n\nУчебное условие: действующий регламент этого центра требует сохранять подтверждённую последовательность и предусмотренные законом приоритеты."},{"case_key":"bank-curated-v2-26","old_hash":"8c30ea4c8477e328821115583107b3f8","situation":"После закрытия цеха центр занятости предлагает всей группе курс веб-дизайна. Подрядчик уже набрал места, но вакансии по этому направлению находятся далеко и требуют цифровых навыков, которых у части работников нет. Токарь Николай показывает предложение местного сервиса: короткое обучение ремонту техники с практикой. Ещё один работодатель готов принять учеников по другому профилю. У работников различаются опыт, состояние здоровья и возможность ездить. Участнику нельзя обещать гарантированное трудоустройство только по устному намерению работодателя; условия практики и вакансий требуют проверки. В учебном условии служба занятости предварительно проверяет принадлежность каждого человека к предусмотренной законом категории и региональный перечень востребованных профессий."},{"case_key":"bank-curated-v2-27","old_hash":"4ec4e8ed775cb16581897c5b4ca3fa3d","situation":"Организаторы консультационного голосования о развитии района объединили строительство парка и введение парковочной платы в один ответ «Поддерживаю». Софья согласна с парком, но предлагает другой источник денег. В обсуждении уже появились голоса против всего пакета, хотя их авторы поддерживают благоустройство. Бюллетени ещё не напечатаны, окончательный результат не объявлен. Организатор может уточнить процедуру и одинаково известить приглашённых о новом сроке. Это общественная консультация, которая сама не вводит плату и не утверждает бюджет; последующие решения требуют компетентного органа и собственного правового основания.\n\nДля учебного примера это консультативный муниципальный опрос по статье 46 закона № 33-ФЗ. Представительный орган утверждает уточнённые вопросы и порядок с соблюдением применимых сроков оповещения и равных возможностей."},{"case_key":"bank-curated-v2-28","old_hash":"54c9b0711dc132fe980f6101a61f6dfa","situation":"После подтопления добровольцы приехали вывозить испорченную мебель. В один дом направили три машины, два подтверждённых адреса остались без помощи. Координатор Роман получил обезличенную карту запросов и контакт штабного ответственного. Часть работ безопасна после проверки помещения; к повреждённой электропроводке должны подходить только подготовленные специалисты. В разных чатах уже пересылают имена и телефоны семей. Желание помочь не делает человека аварийным спасателем, а создание координации не требует принудительного трудоустройства всех добровольцев в муниципальный штат."},{"case_key":"bank-curated-v2-29","old_hash":"5cac6c7095b46f4b34ed801bf9173b12","situation":"В старом жилом доме промерзают стены. Фасад охраняется как часть объекта культурного наследия, а дешёвый проект утепления закроет лепнину. Одновременно акт подтвердил повреждение внутренней отопительной сети. Подрядчик уже привёз облицовку, но разрешительные документы на неё не оформлены. Специалист по наследию предлагает проверить иной проект; инженер видит доступные временные внутренние меры после оценки безопасности. Жильцы ждут улучшения условий сейчас, а не изменения облика ради отчёта. Доставленные материалы не подтверждают законность их применения и не отменяют потребности в безопасном жилье. Работы на внутренней сети выполняются только после определения их вида и соблюдения применимой процедуры охраны, включая предусмотренные уведомление или разрешение; временные меры не затрагивают предмет охраны."},{"case_key":"bank-curated-v2-30","old_hash":"3e70527c44aac49ad4e672df7a4af7e7","situation":"Аналитик Борис рассчитал автобусную нагрузку по числу зарегистрированных жителей. Комендант общежития сообщила, что в заселённом корпусе живут сотни студентов, почти не попавших в эту базу. В утренний час люди остаются на остановке. Перевозчик может подсчитать посадки по рейсам и предложить один дополнительный выход; новую схему сети рассмотрят через месяц. У учреждения есть поимённый список жильцов, но транспортной модели прежде всего нужны обезличенные объёмы поездок и время спроса. Наличие персонального реестра не означает, что его следует целиком передать перевозчику или опубликовать."},{"case_key":"bank-curated-v2-32","old_hash":"9972e52632863f3944e59856455c8d33","situation":"По утрам домашние гуси переходят улицу возле школы. Хозяин ссылается на старую привычку, но теперь на участке плотное движение. Дети останавливаются смотреть на стаю, машины тормозят у перехода. Инспектор может на время организовать безопасный режим, а ветеринар и владелец готовы в течение смены проверить другой путь вывода птиц. Объезд для машин возможен, но длиннее. Старшинство привычки не отменяет действующие требования безопасности, а недовольство пробкой не оправдывает жестокого обращения с птицами."},{"case_key":"bank-expanded-serious-01-01","old_hash":"dac567d95e64012e6ed90fee71062d5c","situation":"6 апреля 2026 года прокуратура сообщила о расселении дома № 6 на улице Якутской в Челябинске. Дом признали аварийным в январе 2024 года, расселение назначили на 2035 год. После обрушения чердачного помещения в квартире образовалась дыра в потолке; жительнице предоставили маневренное жильё. По иску прокурора суд сократил срок расселения, участок изъяли для муниципальных нужд. На 1 апреля расселили семь жилых помещений, работа по ещё одному продолжалась.\n\nЭто учебное продолжение опубликованного сообщения, не заявление о нынешнем статусе дома. Судебное решение исполняется в установленные сроки; для собственников и нанимателей применяется соответствующее основание жилищного обеспечения. Предоставление иного помещения собственнику при изъятии требует законного основания и соглашения; временное размещение не отменяет постоянное обеспечение. Персональные сведения не публикуются."},{"case_key":"bank-expanded-serious-02-01","old_hash":"283db126ded0f101c31843c66bc3056f","situation":"В маловодный период насосная станция подаёт в посёлок только две трети обычного объёма воды. Руководитель водоканала предлагает новый совместный водозабор с соседним районом; его проектирование займёт месяцы. Между тем обследование выявило устранимую утечку на муниципальной магистрали, а подтверждённые точки подвоза позволяют временно обеспечить больницу и жилые кварталы. Санитарные показатели действующего источника ещё должны проверяться по установленному контролю. Дежурный график нужен сегодня.\n\nМуниципальная система обслуживается уполномоченным оператором; безопасный подвоз и санитарный контроль обязательны. Новый водозабор возможен только при законном основании водопользования, санитарной проверке и предусмотренных согласованиях; расходы требуют надлежащего финансового основания."},{"case_key":"bank-expanded-serious-03-01","old_hash":"901b23b6909d9bc3319166d22e76671d","situation":"За две недели до ожидаемых заморозков обследование котельной выявило износ основного насоса. Резервный агрегат исправен, но его подключение не испытано под нагрузкой. На одной бюджетной строке предусмотрены деньги и на ремонт, и на закупку нового резерва; на оба заказа суммы не хватит. Инженер допускает плановый короткий ремонт при заранее проверенном резерве, стационар просит точный период переключения. Дополнительное финансирование возможно обсуждать позднее, оно ещё не выделено.\n\nОтветственная теплоснабжающая организация установлена. Резерв технически проверен, теплоснабжение стационара обеспечено; допустимость переключений определяется специалистами и согласованным безопасным режимом."},{"case_key":"bank-expanded-serious-05-01","old_hash":"a418ca28a18ee0f15f02ed2ad62838c0","situation":"22 апреля 2026 года прокуратура Челябинской области сообщила о проверке школьных перевозок в Сосновском районе. С 18 февраля по 27 марта из-за неисправности четырёх автобусов МОУ «Полетаевская СОШ» был приостановлен подвоз 224 учащихся из десяти населённых пунктов. СМИ писали, что дети ездили на занятия по очереди. Ответственному органу образования предстоит восстановить подвоз: установить потребность по поселениям и сменам, проверить исправность транспорта и наличие водителей, оформить расходы."},{"case_key":"bank-expanded-serious-07-01","old_hash":"9947683636bade32c2cac2e29a53adb2","situation":"9 апреля 2024 года Генпрокуратура сообщила о помощи эвакуированным при паводке в Оренбургской области. В Орске комиссия проверяла социальные услуги в ПВР на базе школы № 15. Со Сбербанком и Социальным фондом обсуждали выплаты и технические средства реабилитации, с МВД и Росгвардией — охрану подтопленных территорий. ПВР на базе больницы Новотроицка предназначался для людей, нуждавшихся в специализированной медицинской помощи. Размещённым людям нужны разные услуги, которые оказывают разные ведомства."},{"case_key":"bank-expanded-serious-22-01","old_hash":"2789f2280472f88c3cffeb39f7755c35","situation":"3 декабря 2025 года прокуратура Забайкальского края сообщила о проверке Александрово-Заводской средней школы. Родители и СМИ жаловались на еду с плесенью. Районная прокуратура привлекла специалистов Роспотребнадзора; сообщение касалось санитарных нарушений при организации питания. Решение принимается на условный момент после обнаружения нарушений, до их устранения; это не описание текущего состояния школы."},{"case_key":"bank-legal-2026-001","old_hash":"7a34e1d26da6e77b5b422e987c9c9cb9","situation":"В Адыгее грант экотуристической фирме предложено перечислить до отбора получателей: сезон начинается завтра, а критерии комиссии ещё не опубликованы.\n\nПо условиям истории предусмотрены 2,4 млн ₽ поддержки и три потенциальных получателя. Одна компания уже заказала экскурсионные автобусы, две другие не знают о конкурсе. Срок открытия маршрута не совпадает со сроком обязательного оформления расхода. В распоряжении участника есть проект порядка, письмо предпринимателя и календарь сезона; нужно выбрать действие до передачи платёжного поручения. В учебном условии действующим учебным порядком предусмотрен конкурс, основание для прямого предоставления отсутствует.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Действующий учебный региональный порядок предусматривает конкурс и заключение соглашения для финансового обеспечения затрат; правительство субъекта утвердило собственный порядок отбора по абз. 2 п. 4 ст. 78.5. Маршруты не затрагивают особо охраняемые территории и иные зоны с особыми условиями."},{"case_key":"bank-legal-2026-002","old_hash":"4fa7c755efc8779c3902ad90a6bb2127","situation":"В Башкортостане губернатор обещает конкретному заводу освободить прибыль от налога письмом администрации. Регионального закона о льготе нет.\n\nДиректор завода показывает обещание сохранить 70 рабочих мест и просит налогового инспектора применить письмо к ближайшему авансовому платежу. В налоговых регистрах прибыль уже определена. Юрист администрации не нашёл опубликованного акта с условиями льготы. До срока платежа осталось пять дней, а депутаты готовы рассмотреть предложение на заседании через неделю.\n\nЗавод — обычная российская организация на общем режиме; применимое основание для пониженной ставки не установлено. Срок платежа сохраняется."},{"case_key":"bank-legal-2026-003","old_hash":"6d2488f9f6220e2f5e548c99797a80ce","situation":"В Бурятии федеральная субсидия на очистные требует регионального софинансирования. В проекте бюджета этой строки нет, подрядчик просит аванс.\n\nВ расчёте строительство стоит 90 млн ₽, из которых 18 млн ₽ должен предоставить регион. Федеральное соглашение содержит сроки ввода объекта и условия перечисления средств. Подрядчик подготовил площадку, но казначейство не получило подтверждения ассигнований. Перед вами проект соглашения, смета и выдержка из регионального бюджета; решение требуется до подписания авансового платежа.\n\n90 млн ₽ — условная смета, 18 млн ₽ — региональная доля по проекту соглашения, а не универсальный норматив. Государственный контракт на эти работы ещё не заключён; подготовка площадки сама по себе не создаёт денежного обязательства бюджета. Применяется обычная субсидия по статье 132 БК РФ; специальный режим части 15 статьи 15 Закона №431-ФЗ и иные исключения не заданы."},{"case_key":"bank-legal-2026-004","old_hash":"4ec81b6a8bacee300e6bacc1d67fc44b","situation":"В Республике Алтай муниципальный совет предлагает туристический налог 5% уже в 2026 году. Отель включил сумму в новый прайс.\n\nСовет обсуждает проект решения на очередной сессии, а владельцы гостиниц уже уведомили гостей о новых ценах. В таблице администратора смешаны предельная ставка соответствующего года и ставка будущего периода. Один турист забронировал номер заранее и требует объяснить изменение стоимости. Участнику доступны календарь введения налога, проект муниципального акта и расчёт на одну ночёвку.\n\nВ рассматриваемом муниципалитете туристический налог уже введён надлежащим актом; гостиница оказывает облагаемую услугу обычному гостю без освобождений. Обсуждается будущая законная ставка, а не перерасчёт по ещё не принятому проекту. Минимальный налог для облагаемой услуги рассчитывается по самостоятельному правилу; изменение договорной цены и возврат гостю не выводятся автоматически из налоговой ставки."},{"case_key":"bank-legal-2026-005","old_hash":"1e23daf3f698be7c432df9ae9c5b473b","situation":"В Дагестане субвенцию на переданное полномочие хотят направить на городской фонтан. Администрация ссылается на одинаковую водную тематику.\n\nСредства поступили с кодом целевого назначения, отдельным отчётом и сроком выполнения переданного полномочия. Проект фонтана стоит 6 млн ₽ и поддерживается частью жителей, но отсутствует в соглашении о субвенции. Бухгалтер предлагает поменять название расхода в заявке, сохранив его содержание. Участник проверяет соглашение, смету и объём ещё неисполненных обязательств переданных полномочий.\n\nПереданное государственное полномочие исполняет муниципальный район. Субвенция поступила ему именно из бюджета субъекта РФ; задача не относится к прямой федеральной субвенции региону.\n\nПереданное полномочие и целевое назначение субвенции установлены условием задачи; фонтан и иные меры благоустройства к этому полномочию не относятся. Субвенция не расходована на фонтан; все обязательства по переданному полномочию сохраняются."},{"case_key":"bank-legal-2026-006","old_hash":"147f4e9dd791ddab63ae77f8542c58d7","situation":"Казённая школа Ингушетии планирует принять обязательство на ремонт сверх доведённых лимитов. Директор обещает закрыть разницу будущей платной кружковой работой.\n\nСогласно смете школе доведено 3 млн ₽, а подрядчик предлагает договор на 4,2 млн ₽. Акт обследования подтверждает необходимость ремонта, однако собственные доходы следующего года ещё не получены. Платёжный график предусматривает аванс до начала работ. На столе у участника лежат смета, лимиты и договор; директор просит решить вопрос до окончания срока предложения подрядчика.\n\nПроект договора не подписан; 3 млн ₽ — доступный остаток соответствующих ЛБО после учёта ранее принятых обязательств. Закупается обычный ремонт по 44-ФЗ, специальные исключения из лимитов неприменимы. Опасные помещения не используются до устранения угрозы; безопасное обучение организуется независимо от выбора дополнительных мер."},{"case_key":"bank-legal-2026-007","old_hash":"54b2def44ab16499ba78cf9a2746c490","situation":"В Кабардино-Балкарии концессионер канатной дороги требует гарантию доходности на 15 лет. Будущие выплаты не включены в бюджетный прогноз.\n\nВ проекте соглашения есть компенсация недополученной выручки при снижении туристического потока. Сумма может достигнуть 12 млн ₽ в год, но приложение к прогнозу содержит только расходы текущего сезона. Банк считает обещание региона достаточным обеспечением кредита. Участник получил три сценария посещаемости и должен оценить не только первый платёж, но и обязательства будущих периодов.\n\nПредполагается допустимый по статье 4 закона №115-ФЗ объект туристической инфраструктуры в публичной собственности, либо создаваемый с возникновением такой собственности. Соглашение пока не заключено."},{"case_key":"bank-legal-2026-008","old_hash":"ad67b790bfed36672a616cfa9f71b1ad","situation":"В Калмыкии земли сельскохозяйственного назначения используют по назначению. Налоговый орган начислил земельный налог по ставке 1,5% без проверки категории.\n\nВ кадастровой выписке указаны категория и разрешённое использование, а акт осмотра подтверждает выпас скота. Налоговое уведомление сформировано по шаблону для иного участка. Собственник просит ответ до срока уплаты и не оспаривает площадь земли. Участнику доступны выписка, муниципальные ставки и расчёт; спор касается правового основания ставки, а не размера дохода хозяйства.\n\nСобственник — физическое лицо, использующее сельхозучасток для сельскохозяйственного производства (выпаса скота). Документы и фактическое использование подтверждены; спор не касается ИЖС. Уведомление содержит ошибку налогового органа, применимый местный акт не позволяет превышать предел НК РФ."},{"case_key":"bank-legal-2026-009","old_hash":"680ee6a8b9a6eea4bd18dfa6616ac652","situation":"В Карачаево-Черкесии член комиссии по субсидиям рассматривает заявку фирмы своего брата и участвует в оценивании. Это обнаружено до утверждения протокола.\n\nДве заявки отличаются по оборудованию и плану занятости, а оценочные листы ещё не подписаны. Член комиссии сообщил о родстве только после вопроса секретаря и предложил голосовать «как обычный эксперт». В составе комиссии есть замещающий участник.\n\nДополнительное условие учебной истории: этот член комиссии участвовал в двух предыдущих отборах; нарушения по ним не установлены.\n\nПо условию учебной истории член комиссии является государственным гражданским служащим, на которого распространяется обязанность предотвращения и урегулирования конфликта интересов; порядок его участия и замещения установлен актом о комиссии.\n\nУстановлен статус государственного гражданского служащего, личная заинтересованность в связи с близким родством и обязанность уведомить уполномоченное лицо. Затронутые оценки пересмотрены независимым составом по прежним критериям. Сведения о прошлых отборах не означают доказанности нарушений."},{"case_key":"bank-legal-2026-010","old_hash":"c6f89f1be13ff21c81ef9398065b2c47","situation":"В Карелии предлагают оставить в местном бюджете все платежи по аренде лесных участков независимо от принадлежности участка и норм зачисления.\n\nВ реестре есть федеральный лесной участок и участок иной публичной собственности. Проект доходной части объединяет оба договора аренды в одну строку местных поступлений. Финансист намерен направить ожидаемые деньги на освещение поселения. Перед вами выписки о собственности и условия аренды; необходимо проверить, какие поступления действительно доступны этому бюджету.\n\nФедеральный участок расположен на землях лесного фонда; второй — на землях иной категории, в муниципальной собственности и не относится к исключениям статьи 62."},{"case_key":"bank-legal-2026-011","old_hash":"b78495780194a7863e5560e295f15f77","situation":"В Коми резервный фонд исполнительной власти хотят использовать для ежегодного планового праздника. Непредвиденных обстоятельств не возникло.\n\nПраздник проводится каждый год, дата известна с начала бюджетного планирования. Организатор не получил ассигнования по обычной программе и предлагает провести оплату через резерв. В фонде предусмотрены деньги на внезапные аварии коммунальной инфраструктуры. Участник изучает положение о резервном фонде, заявку и календарь расходов до подготовки распоряжения об использовании средств.\n\nВ учебном условии действующее положение о резервном фонде не предусматривает финансирование этого ежегодного мероприятия по иным основаниям.\n\nПраздник — обычное плановое мероприятие; специальное основание по установленному порядку фонда прямо исключено условием. Все расходы могут только предлагаться в пределах компетенции, при наличии отдельного законного источника, надлежащих бюджетных ассигнований и доступных ЛБО."},{"case_key":"bank-legal-2026-012","old_hash":"b68b6c9d0f8a64728adff39f5341d966","situation":"В Марий Эл бухгалтер включил права на программу для ЭВМ в базу налога на имущество организаций наряду с недвижимостью.\n\nКомпания приобрела офисное здание и исключительное право на программу по разным договорам. В учётной ведомости оба объекта объединены по признаку высокой стоимости. Инспектор просит пояснение о составе налоговой базы за квартал. Участник получает бухгалтерские документы и характеристики активов; решение должно учитывать вид объекта, а не только строку его отражения в общем отчёте.\n\nПрава на программу приобретены отдельным договором и учтены как отдельный нематериальный актив; они не являются частью стоимости самого объекта недвижимости. Организация не использует специальный режим, изменяющий квалификацию рассматриваемого объекта. Сохраняется налоговая обязанность по зданию при наличии установленных признаков."},{"case_key":"bank-legal-2026-013","old_hash":"19d5de69761a0e96578925cb126ba994","situation":"В Мордовии муниципальный район получает дотацию на выравнивание. Региональный чиновник требует вернуть её за несогласованный цвет благоустройства.\n\nДеньги перечислены на выравнивание бюджетной обеспеченности, а не по соглашению о конкретном благоустройстве. Цвет покрытия выбран местным советом в рамках отдельного проекта. Письмо о возврате не содержит расчёта нарушения и ссылки на условие предоставления дотации. Участнику нужно сопоставить назначение трансферта, полномочия сторон и документы требования до ответа финансовому органу.\n\nВ учебной истории дотация действительно является дотацией на выравнивание бюджетной обеспеченности муниципального района, а не субсидией. Проект благоустройства относится к полномочиям муниципалитета, расход законен, все применимые условия ст. 136 и соглашений соблюдены; нарушения бюджетного законодательства или иного самостоятельного основания взыскания не установлено."},{"case_key":"bank-legal-2026-014","old_hash":"56c2be209efc5df5bf08b4b165cd52dc","situation":"В Якутии авария теплотрассы требует срочного ремонта. Управление хочет применить закупку у единственного поставщика без описания аварии и объёма срочных работ.\n\nАкт диспетчера фиксирует разрыв трубы и угрозу остановки отопления нескольких домов. Подрядчик готов устранить аварийный участок за 48 часов, но в предложении дополнительно указан плановый ремонт соседней магистрали. Финансирование срочной части определено в резерве. Участник получил фотографии, дефектную ведомость и две сметы; необходимо отделить аварийную потребность от работ, которые могут пройти обычную процедуру.\n\nЗаказчик действует по 44-ФЗ, наличие аварии подтверждено, конкурентный срок нецелесообразен именно для минимально необходимого аварийного объёма. Отдельная плановая замена не включается в аварийное основание."},{"case_key":"bank-legal-2026-015","old_hash":"8a4bcdd64422fbfeba5566eb50023f85","situation":"В Северной Осетии предлагают государственную гарантию по кредиту клуба без анализа финансового состояния принципала и бюджетного оформления.\n\nКлуб просит обеспечение кредита на строительство тренировочной базы сроком на семь лет. В пакете есть презентация посещаемости, но отсутствует проверка финансового положения и обеспечение обратных требований. Предельный объём гарантий в бюджете уже частично занят. Перед вами проект гарантии, долговая книга и заявка банка; решение нужно принять до выпуска письма о поддержке.\n\nКлуб — частное юридическое лицо, не относящееся к специальным исключениям из требований гарантии. Региональная гарантия планируется с регрессом; до выдачи требуются анализ финансового состояния, предусмотренное обеспечение, правовое решение, бюджетные пределы и договор. Письмо поддержки не выдано."},{"case_key":"bank-legal-2026-016","old_hash":"a9cbcbec00aec7deff783345eb99106b","situation":"В Татарстане промышленная субсидия возмещает покупку оборудования. Заявитель представил один и тот же счёт для двух программ возмещения.\n\nОба отчёта относятся к одному станку, одной накладной и одной дате оплаты. Первая программа покрывает часть покупки, вторая рассчитана на другой набор подтверждённых затрат. Получатель считает, что разные названия программ допускают повторное возмещение. Участник проверяет соглашения и документы об оплате до утверждения суммы; отдельно нужно проверить корректность уже представленного отчёта.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Две действующие учебные программы возмещения прямо исключают повторное возмещение одной и той же части затрат. Вторая программа не охватывает данный станок; первая выплата ещё не удваивается, вторая заявка не оплачена. Подтверждённые затраты учитываются с учётом применимого режима НДС."},{"case_key":"bank-legal-2026-017","old_hash":"1e599cf4425e8418c2ffc4d018f4fcec","situation":"В Тыве банк предлагает кредит, после которого плановый долг превысит допустимый для конкретного региона предел. Ответственный сравнил только процентную ставку.\n\nВ таблице заимствований не учтены два действующих обязательства, а доходная база включает целевые поступления. Кредит дешевле альтернативы на один процентный пункт, но требует погашения в следующем году. Финансовый орган должен представить расчёт допустимого объёма долга на заседании. Участнику доступны долговая книга и проект доходов; выбрать действие нужно до подписания кредитного договора.\n\nУчебный расчёт учитывает все долговые обязательства и определённую БК РФ доходную базу; применимые к субъекту временные исключения, верхние пределы и показатели устойчивости проверены. Предлагаемый кредит превышает установленную для этой задачи границу, подписания ещё нет."},{"case_key":"bank-legal-2026-018","old_hash":"18f57fbc5cf84238fd4a518d1c9bb51b","situation":"В Удмуртии открытый конкурс на поставку содержит сведения ограниченного доступа. Заказчик намерен опубликовать весь технический пакет вместе с извещением.\n\nПоставщик прислал техническое приложение, часть которого отмечена как сведения ограниченного доступа. Электронная площадка предлагает общий режим размещения файлов. Сотрудник закупок хочет ускорить публикацию, чтобы не сорвать производственный график. Участник получил отметки о режиме информации и проект документации; необходимо определить процедуру и состав раскрываемых сведений до отправки извещения.\n\nСведения компетентным образом отнесены к охраняемой законом информации; если они составляют государственную тайну или имеется иное основание части 11 статьи 24, применяются закрытые способы по установленной процедуре. Простая отметка поставщика сама по себе не определяет режим."},{"case_key":"bank-legal-2026-019","old_hash":"999fb48762be6a17e4b7027592c2dd88","situation":"В Хакасии предприятие просит уменьшить НДПИ на расходы, не подтверждённые документами и не относящиеся к предусмотренному вычету.\n\nПредприятие предъявило платежи за ремонт административного здания вместе с расходами производственного участка. Документы о назначении затрат представлены не полностью. В декларации уже рассчитана сумма предполагаемого уменьшения налога. Участнику доступны счета, акты и перечень заявленных расходов; решение требуется до подачи уточнений, с проверкой связи каждой суммы с установленными условиями вычета.\n\nПредприятие добывает уголь; в налоговой учётной политике выбран вычет по НДПИ. Административный ремонт не связан с обеспечением безопасных условий и охраны труда на данном участке недр."},{"case_key":"bank-legal-2026-020","old_hash":"e51682ad566f63aef1ea93915bb0792a","situation":"В Чечне временно не хватает денег на уже предусмотренные обязательства. Участник называет кассовый разрыв новым дефицитом бюджета и предлагает отменить все расходы.\n\nКассовый план показывает поступление доходов через десять дней, тогда как зарплата и договорные платежи должны пройти на этой неделе. Годовые ассигнования и ожидаемые доходы не изменились. В служебной записке смешаны остаток денег на счёте и годовой баланс.\n\nНа дату оценки годовой баланс не изменился; разрыв прогнозируется на едином счёте регионального бюджета. Действующие обязательства исполняются в установленные сроки."},{"case_key":"bank-legal-2026-021","old_hash":"dbad1b54310b4135418f73f29a137ad3","situation":"В Чувашии завод получил аванс от иностранного покупателя. Бухгалтер автоматически применил нулевой НДС ко всем внутренним продажам этого месяца.\n\nВ одном месяце завод реализовал продукцию за рубеж и покупателям внутри страны. Экспортный комплект подтверждений ещё собирается, но бухгалтер перенёс одну ставку на весь журнал продаж. Покупатель внутренней партии просит корректный счёт-фактуру. Участник получает договоры, отгрузочные документы и реестр аванса; важны вид операции и её подтверждение, а не валюта отдельного поступления.\n\nОктябрь 2026 года. Обычные облагаемые товары вывозятся за пределы ЕАЭС в процедуре экспорта; отказ от нулевой ставки не заявлен. Внутренние продажи обычных товаров не подпадают под освобождение или пониженную ставку."},{"case_key":"bank-legal-2026-022","old_hash":"bf072498f6f631253a98170072df7777","situation":"В Алтайском крае возмещение агростраховых затрат заявляет хозяйство без действующего договора страхования. Оно предлагает позже донести полис.\n\nХозяйство представило расчёт затрат и письмо страхового агента, но договор ещё не вступил в силу. В регионе начинается посевная, и фермер просит аванс на семена. Порядок поддержки содержит перечень подтверждающих документов и срок подачи.\n\nЗаявка касается именно субсидирования сельскохозяйственного страхования, не аванса на семена. Договор не вступил в силу, необходимые документы и выполнение требований к премии отсутствуют. Условия различаются в зависимости от страхового события и статуса производителя; конкретная ставка не предполагается."},{"case_key":"bank-legal-2026-023","old_hash":"93f88b70063bd12b27dd63824d6cbc63","situation":"В Краснодарском крае администрация вводит обязательный сбор за проход к общедоступному берегу, называя его неналоговым доходом бюджета.\n\nНа входе установлена будка оплаты, а альтернативный проход перекрыт ограждением арендатора. Местный бюджет планирует получить 1,8 млн ₽ за сезон. В проекте акта термин «услуга» применяется к самому проходу, без отдельной услуги посетителю. Перед вами схема берега, договор аренды и проект решения; нужно проверить правовую природу платежа и доступ граждан.\n\nДополнительное условие учебной истории: потребность в регулярной уборке подтверждена, а в муниципальном бюджете есть ассигнования на эту цель; их перераспределение не считается состоявшимся.\n\nПо условию учебной истории берег регулярно загрязняется, посетители жалуются именно на отсутствие уборки, добровольные акции нерегулярны.\n\nПо условию учебной истории это водный объект общего пользования; специальные законные ограничения доступа не установлены.\n\nБереговая полоса относится к водному объекту общего пользования; специальных законных ограничений нет."},{"case_key":"bank-legal-2026-024","old_hash":"7962817e6516a248d20b61e0928008b0","situation":"Красноярский край включил разовое поступление от продажи имущества в постоянную базу финансирования зарплат. Следующие три года продажи не ожидается.\n\nПродажа склада даст бюджету 140 млн ₽ в первом году. В расходном плане на эту сумму назначены постоянные выплаты, а повторного имущества для продажи нет. При ухудшении доходов обязательства по зарплате сохранятся. Участник получил трёхлетний прогноз и ведомость имущества; решение требует сопоставить устойчивость источника с характером финансируемого расхода.\n\nСклад — объект казны субъекта РФ; не акции, доля в капитале, драгоценные металлы либо имущество учреждения или унитарного предприятия. Продажа законно оформлена. В следующих периодах повторных поступлений нет. Действующие выплаты сохраняются; новые меры подлежат утверждению уполномоченным органом."},{"case_key":"bank-legal-2026-025","old_hash":"1a6dbaf9b2de51e413061bbe4ebdfcbb","situation":"В Приморском крае инвестору обещано освобождение от всех федеральных налогов региональным соглашением. Заявитель просит заверить обещание печатью.\n\nИнвестор планирует склад и просит приложить письмо администрации к кредитному досье. В перечне обещанных льгот смешаны федеральные и региональные платежи. Опубликованного основания для части обещаний нет, но презентация уже распространяется среди партнёров. Участник сопоставляет соглашение и полномочия публичного органа до заверения документа; коммерческий эффект обещания не заменяет его правовое основание.\n\nСоглашение не относится к специальному федеральному режиму, дающему предусмотренные НК РФ гарантии или освобождения; в рассматриваемом случае отсутствует федеральное основание полного освобождения."},{"case_key":"bank-legal-2026-026","old_hash":"cfa431822d8732902e37a4f97689fda8","situation":"В муниципалитете Ставропольского края, где туристический налог введён, гостиница включила в налоговую базу стоимость проживания лица, подпадающего под федеральное исключение: местный совет не продублировал его.\n\nПостоялец предъявил документ о статусе до окончательного расчёта. В программе учёта предусмотрен только перечень из местного решения. Менеджер просит разъяснить порядок. Участник получает расчёт проживания и подтверждающий документ; необходимо отдельно определить налоговое исключение и порядок корректировки договорного расчёта.\n\nВ учебном условии договор на отдельную услугу проживания заключён непосредственно с лицом из категории пункта 2 статьи 418.4 НК РФ; документ представлен гостинице.\n\nПодтверждённый статус — Герой Российской Федерации (подп. 1 п. 2 ст. 418.4). Это отдельная услуга проживания, оказанная непосредственно предъявившему документ гостю, без объединения с оплатой за других лиц. Гостиница исполняет налоговые обязанности по прочим облагаемым услугам."},{"case_key":"bank-legal-2026-027","old_hash":"ae2d59f938c849148c8ac675c3021fe7","situation":"В Хабаровском крае аванс подрядчику направляют на обычный счёт, хотя условия финансирования требуют казначейского сопровождения.\n\nКонтракт предусматривает аванс 30 млн ₽ на материалы, с отдельным порядком сопровождения. Подрядчик направил реквизиты своего обычного банковского счёта и обещал отчитаться накладными позднее. Финансовый орган видит несоответствие условиям выделения денег. Участник изучает контракт, соглашение о финансировании и реквизиты до платежа, учитывая назначение средств и правила их дальнейшего движения.\n\nУсловиями задачи прямо исключено применимое законное исключение для перечисления данного аванса на обычный счёт.\n\nОбязательность казначейского сопровождения именно этого аванса установлена правовым основанием и контрактом; применимые исключения перечисления на обычный счёт отсутствуют. Сопровождение не является банковским эскроу."},{"case_key":"bank-legal-2026-028","old_hash":"29cc6a7f1aa0c3072ac713eb3f590531","situation":"В Амурской области субсидию обещали устно. Получатель уже начал строительство и требует перечислить деньги без соглашения и проверок условий.\n\nВ переписке есть согласование идеи проекта и предварительная оценка объёма помощи. Соглашение не подписано, показатели результата и условия возврата не определены. Подрядчик выставил счёт за уже начатые работы заявителя. Участник получил письма, проект порядка поддержки и подтверждение расходов; нужно отделить фактические ожидания получателя от основания бюджетного обязательства.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Здесь запрашивается субсидия на финансовое обеспечение будущего отдельного этапа, а не предусмотренное пп. «е» п. 11 общих требований единовременное возмещение уже достигнутого результата без соглашения. Учебный порядок предусматривает конкурс, письменное соглашение и не содержит прямого назначения данного получателя."},{"case_key":"bank-legal-2026-029","old_hash":"9274bff091ffb4ccab936967027dbf9e","situation":"Архангельская область сравнивает показатели долга с доходами, включая показатели автономного округа дважды. Расчёт используют для предельного заимствования.\n\nВ исходной таблице одна строка содержит данные области без автономного округа, другая содержит консолидированный итог с округом. Аналитик складывает обе строки и получает завышенную доходную базу. От этого расчёта зависит допустимый объём нового кредита.\n\nОценивается долг именно Архангельской области, а не НАО. Для расчёта используются утверждённые показатели отдельного областного бюджета с предусмотренными законом исключениями и актуальный объём его обязательств. Статус субъекта, действующие специальные нормы и пределы проверяются финансовым органом до нового займа; задача не предполагает вычисления неизвестного предела или нового кредита по одному показателю."},{"case_key":"bank-legal-2026-030","old_hash":"29834e39549e1d83a5db4ed95bfa8678","situation":"В Астраханской области фирма получила разрешение на водные биоресурсы, но рассчитывает сбор по вылову вместо показателей, установленных для этого разрешения.\n\nВ разрешении указаны виды ресурсов и объёмы, а журнал судна отражает меньший фактический улов. Бухгалтер уменьшил платежи пропорционально разнице и не проверил порядок расчёта сбора. Срок внесения очередной суммы приближается. Перед вами разрешение, журнал и расчёт; необходимо определить правовое основание базы и порядок исправления платежа при различии этих сведений.\n\nДействующее в 2026 году разрешение на обычное коммерческое рыболовство содержит виды и объёмы разрешённой добычи; разрешение не изменено. Специальный вычет или исключение из обычного порядка неприменимы."},{"case_key":"bank-legal-2026-031","old_hash":"409c11fd3b837d9f2736899919d5b351","situation":"В Белгородской области чрезвычайная помощь выделена на восстановление склада. Получатель направил её на приобретение нового автомобиля руководителя.\n\nВ соглашении перечислены восстановительные работы и требования к подтверждению затрат. Платёж за автомобиль обнаружен при проверке промежуточного отчёта, пока большая часть помощи ещё не освоена. Получатель объясняет покупку необходимостью руководителю ездить на объект. Участник получает смету, выписки и акт осмотра; решение касается назначения расхода и дальнейшей судьбы помощи, а не общей полезности машины.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Помощь — субсидия по ст. 78 на финансовое обеспечение перечисленных в соглашении работ. Автомобиль не входит в разрешённые расходы, исключения или обстоятельства непреодолимой силы отсутствуют. Главный распорядитель устанавливает соответствующую сумму возврата по учебному порядку; обязательное требование о возврате не зависит от голосования."},{"case_key":"bank-legal-2026-032","old_hash":"537d870612f3b60b63d7954c610b25f8","situation":"В Брянской области транспортную субсидию рассчитывают за рейсы, которые отменены. Перевозчик представил плановое расписание вместо фактических данных.\n\nВ отчётном месяце фактически выполнено 62 рейса из 80 запланированных. Одни рейсы отменены из-за погоды, другие из-за неисправности автобуса. Порядок возмещения предусматривает расчёт подтверждённой транспортной работы. Участник получил путевые листы, расписание и заявку на субсидию; необходимо установить, какие данные использовать и как зафиксировать расхождения до перечисления средств.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Речь о возмещении из регионального бюджета по учебному соглашению, а не об оплате одного и того же объёма по двум основаниям.\n\nНормативный порядок и соглашение определяют возмещение по подтверждённой фактической работе: 62 рейса из 80. Применимость договора регулярных перевозок и субсидии разграничена; один объём не финансируется повторно. Отменённые рейсы не входят в базу именно данной субсидии."},{"case_key":"bank-legal-2026-033","old_hash":"5af87fc5d12688f03f41605f053c7c13","situation":"Во Владимирской области бюджетному музею уменьшают субсидию на задание, не меняя объём задания и не обосновывая изменение нормативных затрат.\n\nМузей должен провести то же число выставок и экскурсий, что предусмотрено действующим заданием. Уменьшение финансирования объясняется общим желанием экономии, без изменения расчёта нормативов. Сотрудники предупреждают о закрытии части экспозиции. Участник сопоставляет задание, расчёт затрат и проект соглашения; решение требуется до уведомления учреждения о новом объёме субсидии.\n\nМузей является учреждением субъекта РФ. В учебном условии учредитель не применяет специального порядка перераспределения расходов на содержание имущества или налоги и не представил иного законного расчёта изменения финансового обеспечения.\n\nМузей — бюджетное учреждение субъекта РФ. В 2026 году проверяется специальный временный порядок статьи 10 закона №431-ФЗ; учредитель не применяет правомерный специальный перерасчёт и не обосновал нормативные затраты. Исключение для федеральных учреждений по индексации не переносится автоматически на региональное."},{"case_key":"bank-legal-2026-034","old_hash":"f24dc3cccd075872d70ca6e17ffe1893","situation":"В Волгоградской области казначейство получило исполнительный документ о взыскании с бюджетного учреждения. Финорган предлагает оставить его без регистрации.\n\nДокумент поступил с судебными реквизитами, заявлением взыскателя и сведениями о получателе. Учреждение просит «подождать переговоров», а срок дальнейших действий уже отсчитывается от поступления. В журнале входящих пока нет записи. Участник получает пакет взыскателя и письма сторон; нужно выбрать процедуру, которая обеспечивает учёт документа и исполнение применимых требований.\n\nДолжник — бюджетное учреждение с лицевым счётом; исполнительный документ поступил в орган, ведущий этот счёт. Применяется часть 20 статьи 30 закона №83-ФЗ, а не общий порядок взыскания с казённого учреждения."},{"case_key":"bank-legal-2026-035","old_hash":"0b0e512a7bec32c85768275b0006b5f3","situation":"В Вологодской области завод рассчитывает налог на имущество по остаточной стоимости объекта, для которого применима кадастровая база и утверждённый перечень.\n\nОбъект включён в опубликованный перечень, а компания использовала старую карточку основных средств. После переоценки остаточная стоимость существенно ниже кадастровой. Бухгалтер предлагает продолжить прежний расчёт до конца года. Участник изучает вид объекта, перечень соответствующего периода и налоговые регистры; важно определить применимое основание базы и период расчёта, а не выгодность суммы для предприятия.\n\nРассматривается 2026 год и принадлежащее заводу отдельное офисное здание, соответствующее признакам административно-делового центра; действующий региональный закон предусматривает кадастровую базу, здание правомерно включено в опубликованный перечень на соответствующий период, кадастровая стоимость определена и внесена в ЕГРН. Исключения подп. 2 и 2.2 п. 12 ст. 378.2 не применяются. Незавершённое оспаривание не меняет расчёт само по себе."},{"case_key":"bank-legal-2026-036","old_hash":"6b74c537219ce393f6540bd55793bddc","situation":"В Воронежской области участок фактически используется для коммерческого склада, хотя заявитель требует льготной ставки как для садоводства.\n\nНа участке размещены ангар, погрузочная площадка и складские договоры с несколькими клиентами. В выписке сохранено прежнее разрешённое использование, а фактическая деятельность изменилась. Собственник ссылается на старое членство в садовом товариществе. Перед вами акт осмотра, выписка и ставки; спор требует сопоставить правовые условия льготы с подтверждённым использованием земли.\n\nСпорный участок является индивидуальным садовым участком, не относится к землям сельхозпроизводства, не является участком общего назначения и используется в подтверждённой предпринимательской деятельности под складом. Иные основания для применения специальной пониженной ставки не заданы."},{"case_key":"bank-legal-2026-037","old_hash":"22bda83c07f1999f6d5ac1cd048da289","situation":"В Ивановской области фабрика просит налоговую отсрочку. Администрация предлагает сама подписать её вместо уполномоченного налогового органа.\n\nУ фабрики снизилась выручка, и к заявлению приложены финансовые документы и план восстановления. В администрации готовы поддержать предприятие, но налоговое решение ещё не принято. Банк просит письменное подтверждение отсрочки для кредитного соглашения. Участник получает проект письма и заявление; требуется определить компетентного адресата и дальнейший порядок рассмотрения до обещания переноса срока.\n\nЗапрашивается обычная отсрочка по региональной части налога на прибыль, а не инвестиционный налоговый кредит. Финансовые трудности требуют проверки предусмотренного законом основания, документов, способности уплатить налог впоследствии и ограничений; положительного решения пока нет."},{"case_key":"bank-legal-2026-038","old_hash":"c04dc65bd28e7776892a17aca646a249","situation":"В Иркутской области предприятие предлагает зачесть добровольный экологический платёж в счёт налога на прибыль без предусмотренного правового основания.\n\nФирма перечислила деньги на восстановление прибрежной территории добровольно, по отдельному соглашению. В расчёте налога бухгалтер механически вычел всю сумму из платежа, не проверив квалификацию расхода. Экологический проект подтверждён фотографиями, но это не налоговый расчёт. Участнику доступны соглашение, документы об оплате и регистры; нужно отделить общественно полезный результат от правового основания уменьшения налога.\n\nПеречислен отдельный добровольный безвозмездный взнос на экологический проект, не являющийся обязательной платой за негативное воздействие; специального налогового зачёта нет."},{"case_key":"bank-legal-2026-039","old_hash":"c4de6f6eac4a881f572d1bde5581eda6","situation":"В Калининградской области фирма требует льготу особой экономической зоны только по месту адреса. Статус резидента и условия деятельности не подтверждены.\n\nКомпания арендовала небольшой офис по нужному адресу, а основное производство находится за пределами заявленной деятельности. В реестре резидентов сведения о ней не найдены. Представитель просит применить льготу с даты аренды офиса. Участник получает договор, описание проекта и налоговый расчёт; необходимо проверить статус, период и условия права на специальный порядок, не ограничиваясь географическим адресом.\n\nОрганизация на общем режиме не включена в единый реестр резидентов ОЭЗ Калининградской области; нет подтверждённого проекта, отвечающего специальным требованиям, и иного основания для льготы."},{"case_key":"bank-legal-2026-040","old_hash":"40cbb5db3a87f27d96acb92bb0c8801d","situation":"В Калужской области условия гранта требуют опыт производства изделия ровно 17 месяцев. Ограничение совпадает с опытом одной фирмы и не обосновано целью поддержки.\n\nКомиссия получила четыре заявки, из которых три отклоняются только по длительности опыта. В пояснении к порядку не показано, почему выбран именно такой срок. Предприятия предлагают подтвердить качество продукции испытаниями. Участнику доступны проект критериев и сравнительная таблица заявок; решение требуется до публикации результатов отбора и должно учитывать проверяемость условий доступа к поддержке.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Отбор — конкурс по учебному региональному порядку в соответствии с абз. 2 п. 4 ст. 78.5 БК РФ. Заключений соглашений и итогового протокола ещё нет."},{"case_key":"bank-legal-2026-041","old_hash":"2827660ddb00d1a9f8a8d24130373cf9","situation":"На Камчатке субсидируют доставку продуктов в труднодоступные районы. В отчёт перевозчика включены коммерческие туристические рейсы без доставки.\n\nПеревозчик объединил в одном реестре доставку продуктов, туристов и собственных сотрудников. Посадочные ведомости и грузовые документы позволяют разделить рейсы. В заявке на возмещение указана общая стоимость топлива.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Для учебной программы расходы на туристические рейсы прямо исключены; совместные рейсы учитываются только в части затрат, обоснованно относимых к доставке.\n\nСубсидия возмещает подтверждённые расходы по доставке продуктов; туристические рейсы без доставки исключены. При совместной перевозке допустима только документально обоснованная доля расходов по утверждённой методике; двойное возмещение исключено."},{"case_key":"bank-legal-2026-042","old_hash":"28d31c4dd9863723067f7d7dd65447be","situation":"В Кузбассе планируют закрыть шахту с задолженностью по зарплате. Помощь регионального бюджета предложено перечислить собственнику без условий защиты работников.\n\nВ досье есть списки работников, задолженность по выплатам и план переобучения. Собственник просит 50 млн ₽ на «стабилизацию», без отдельных показателей использования средств. Муниципалитет опасается роста безработицы после остановки предприятия. Участник изучает цель поддержки, условия соглашения и контроль результата; требуется выбрать способ, связывающий бюджетное решение с фактическим положением работников.\n\nРаботодатель обязан выплачивать заработную плату и расчёт при увольнении независимо от субсидии. Для учебной ситуации предприятие не освобождено от обязательств, специальные правила банкротства не рассматриваются. Региональные программы переобучения и поддержки имеют отдельные законные основания."},{"case_key":"bank-legal-2026-043","old_hash":"b9ef7854c243b0adbd3fed3b2ab165d0","situation":"Кировская область выпускает облигации, но в презентации замалчивает условия погашения и объём действующего долга. Инвесторам предлагают устное обещание досрочного выкупа.\n\nВ проекте размещения есть срок обращения, размер купона и условия досрочного погашения, но рекламная презентация не совпадает с ним. Часть слушателей воспринимает облигацию как вклад с гарантированным досрочным возвратом. Финорган получил запрос о долговой нагрузке. Перед вами условия займа и долговая книга; необходимо определить раскрываемую информацию и порядок исправления сообщения инвесторам.\n\nРазмещение облигаций ещё готовится; эмитентом выступает уполномоченный исполнительный орган субъекта. Действующие долговые обязательства сохраняются, параметры нового выпуска оформляются и раскрываются в установленном порядке. Досрочный выкуп возможен только на соответствующем законном основании."},{"case_key":"bank-legal-2026-044","old_hash":"df3f1c984e1ba10407c87e4bb50cceff","situation":"В Костромской области малый бизнес смешивает выручку ювелирной торговли с деятельностью, для которой специальный режим допустим, и применяет его ко всем операциям.\n\nВ журнале продаж отдельно отражены ювелирные изделия и иная продукция мастерской. Регистрационные документы содержат несколько видов деятельности, но бухгалтер использует один налоговый расчёт для всей выручки. Контрагент запросил подтверждение режима. Участник проверяет применимость специального порядка к конкретным операциям и структуру учёта до сдачи отчётности, не делая вывод только по названию бизнеса.\n\nВ учебном условии продавец — индивидуальный предприниматель, ювелирные товары изготовлены преимущественно из золота, а не серебра; применимое исключение для изделий из серебра не относится к данной торговле.\n\nИП до октября 2026 года правомерно применял УСН, а в октябре начал торговлю золотыми ювелирными изделиями. Исключение для серебра неприменимо. Иная деятельность может рассматриваться для ПСН отдельно при наличии самостоятельного патента и соблюдении всех условий."},{"case_key":"bank-legal-2026-045","old_hash":"572138f40e4213f05ab5a176c91d7266","situation":"В Курганской области на восстановление после паводка перечисляют помощь по списку домов без обследования повреждений. В списке есть непострадавший объект.\n\nКомиссия объехала часть улиц, но один адрес перенесён в список по устному сообщению. Фотографии этого дома не подтверждают повреждений, а владелец просит выплатить помощь вместе с соседями. Срок первого перечисления назначен на пятницу. Участнику доступны акты, фотографии и критерии помощи; необходимо определить, как проверить конкретный адрес и сохранить законное рассмотрение остальных заявок. В учебном условии действует утверждённая программа компенсации имущественного ущерба гражданам; отдельные экстренные меры безопасности и помощи не зависят от данного отбора.\n\nУтверждённая учебная программа предусматривает компенсацию имущественного ущерба гражданам по подтверждённым критериям. Акт обследования спорного адреса пока отсутствует; подтверждённые заявки рассматриваются независимо. Срочные защитные меры и иная экстренная помощь не зависят от данного отбора."},{"case_key":"bank-legal-2026-046","old_hash":"33d0aa5c7a70dbd8e7060fa069de125b","situation":"Курская область получила целевой межбюджетный трансферт, который не использован к концу года. Чиновник предлагает автоматически потратить его в следующем году без решения о потребности.\n\nВ соглашении установлен срок использования, отчётность и порядок подтверждения потребности на следующий год. На счёте осталось 8 млн ₽, работы по одному контракту ещё не закончены. Бухгалтер считает остаток свободным ресурсом для новых расходов. Участник получает акт сверки, контракт и письмо получателя; решение касается дальнейшего использования целевых денег и оформления требуемых подтверждений.\n\nПо условию учебной истории речь идёт об обычной целевой субсидии из федерального бюджета, остаток 8 млн рублей установлен на 1 января; средства не относятся к резервному фонду Президента и не подпадают под специальное исключение.\n\nУчебный остаток обычной целевой субсидии определён на 1 января; действующие специальные исключения отсутствуют."},{"case_key":"bank-legal-2026-047","old_hash":"919f4d2cb235ef1ef13d9d4d10f0bb60","situation":"В Ленинградской области муниципалитет хочет перенести чужую региональную стройку в свой бюджет, не получив передачи полномочий и источника финансирования.\n\nОбъект находится на территории муниципалитета, но заказчиком и носителем полномочия указан региональный орган. Местный совет готов включить стройку в свой перечень расходов уже сегодня. Регион не передал ни обязательство, ни финансовое обеспечение. Участник изучает договоры, реестр полномочий и проект бюджета; необходимо установить надлежащую процедуру взаимодействия уровней власти до появления нового расхода.\n\nРегиональная стройка относится к региональному расходному обязательству и объекту региональной собственности; специальное основание местного финансирования отсутствует. Собственные муниципальные меры координации не переносят обязательство. Возможная передача государственных полномочий требует применимого закона, материальных ресурсов и финансового обеспечения."},{"case_key":"bank-legal-2026-048","old_hash":"91131abfacf00bd4cb4d2c8b0bff1743","situation":"В Липецкой области поддержку обещают за прирост рабочих мест. Фирма заменяет показатель занятости числом заключённых договоров услуг с подрядчиками.\n\nВ соглашении указаны новые рабочие места и сроки сохранения занятости. Компания представила 30 договоров услуг с внешними исполнителями вместо сведений о 30 новых работниках. При этом отчёт включает прежний штат как дополнительный результат проекта. Участнику доступны трудовые сведения и условия поддержки; необходимо определить, какой показатель подтверждён и как оценить выполнение соглашения.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. По действующему учебному соглашению новое рабочее место — отдельная должность, фактически занятая новым работником по трудовому договору, с установленным сроком сохранения занятости. Подрядчики действительно независимы; скрытых трудовых отношений в условии нет. Срок достижения результата ещё не истёк, изменение показателя не производится задним числом."},{"case_key":"bank-legal-2026-049","old_hash":"a33217a81dcccf5af52f4e628d5bfd41","situation":"Магаданская область хочет покрыть дефицит прогнозом добычи по лицензии, которую компания ещё не получила. Доход включён как гарантированный.\n\nПрогноз доходов рассчитывается по мощности будущего участка и максимальной цене металла. Компания ещё проходит процедуру получения права пользования недрами и не утвердила график добычи. В расходном плане уже назначены обязательства под весь прогнозируемый поток. Участник получает лицензирующее досье и несколько ценовых сценариев; нужно оценить подтверждённость предпосылок до утверждения источника покрытия дефицита.\n\nВ истории отсутствует подтверждённое право пользования данным участком недр и подтверждённый график добычи; ожидаемые поступления в региональный бюджет не гарантированы. Величина и распределение конкретных налогов не рассчитываются. Все сценарии составляются для бюджетного планирования; фактические доходы и источники финансирования дефицита разграничиваются."},{"case_key":"bank-legal-2026-050","old_hash":"2b9f68259f0be73a6808876dd725d506","situation":"В Московской области компания считает кадастровую стоимость ошибочной и полностью прекращает уплату налога, не используя процедуру оспаривания и перерасчёта.\n\nОрганизация получила отчёт оценщика с иной стоимостью и направила обращение о пересмотре. Решение компетентного органа по этому обращению ещё не принято, а срок платежа наступил. Бухгалтер исключил налог из платёжного календаря полностью. Перед вами действующие сведения, обращение и расчёт; необходимо определить порядок действий в период спора и условия последующего перерасчёта.\n\nКомпания — собственник облагаемого по кадастровой базе здания в 2026 году; оспаривается действующая, а не архивная стоимость. Применяется порядок ст. 22.1 Закона №237-ФЗ; представлен электронный отчёт, дата оценки и срок подачи отвечают применимым требованиям."},{"case_key":"bank-legal-2026-051","old_hash":"a24df2d84dcf3a53580ea39124f9712b","situation":"В Мурманской области цену долгосрочного контракта увеличивают письмом подрядчика из-за логистики. Основание изменения условий контракта не проверено.\n\nКонтракт предусматривает доставку материалов в несколько портов и фиксированную цену. Подрядчик приложил новые тарифы перевозчиков, но не указал норму и обстоятельство, допускающие изменение соглашения. Часть поставки уже выполнена по прежней цене. Участник получает контракт, график и расчёт логистики; необходимо определить порядок рассмотрения требования до оформления дополнительного соглашения.\n\nКонтракт заключён по 44-ФЗ и исполняется; письмо подтверждает рост затрат, но само по себе не устанавливает предусмотренное статьёй 95 или действующей специальной нормой основание. Возможность применения временных норм 2026 года проверяется по конкретному контракту и решению компетентного органа."},{"case_key":"bank-legal-2026-052","old_hash":"6dd24ac52eea9c22bddbf7c12b2ea8fa","situation":"В Нижегородской области перевозчику выплачивают компенсацию по неподтверждённой оценке выпадающих доходов. Методика расчёта отсутствует в акте.\n\nПеревозчик сравнивает фактическую выручку с максимальной загрузкой депо и объявляет всю разницу убытком. В расчёт включены направления, не относящиеся к льготному проезду. Финорган должен подготовить платёж на следующей неделе. Перед вами данные перевозок и проект акта; нужно проверить основание, границы и метод определения компенсируемого расхода.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Возмещение заявлено как отдельная субсидия на недополученные доходы от льготного проезда, а не плата за работы по государственному контракту.\n\nВ учебной программе заявлена субсидия на возмещение недополученных доходов, отдельно от оплаты работ по транспортному контракту."},{"case_key":"bank-legal-2026-053","old_hash":"7634b9621b88401ee92503bfaa8d6409","situation":"В Новгородской области внутренний финансовый аудит поручают тому же сотруднику, который единолично проводил проверяемые операции и должен оценить собственные ошибки.\n\nПроверяемый сотрудник самостоятельно составлял документы, подтверждал платежи и исправлял выявленные расхождения. Начальник считает, что он лучше всех знает материалы проверки. Отдельная функция оценки эффективности должна дать независимый вывод. Участник получил положение об аудите и перечень операций; необходимо выбрать состав и организацию проверки, сохранив возможность достоверно оценить результат.\n\nПроверяемые операции выполнял сам предлагаемый аудитор. Для учебной ситуации функционально независимый субъект внутреннего финансового аудита определён. Привлечённый эксперт действует по стандарту и не заменяет руководителя аудиторской группы; ни один вариант не разрешает проверять собственные операции."},{"case_key":"bank-legal-2026-054","old_hash":"d632bafc33c2d7653bcc7b56979125b9","situation":"В Новосибирской области грант на исследования требует результатов и отчётности. Получатель просит заменить научный результат рекламным роликом без изменения соглашения.\n\nСоглашение предусматривает прототип, результаты испытаний и отчёт об использовании 5 млн ₽. Получатель подготовил красивую презентацию, но испытания не завершил. В ведомстве опасаются пропустить срок представления отчёта по программе. Участник изучает календарь, показатели и фактические материалы; необходимо определить, какое подтверждение результата допустимо и как рассмотреть просьбу об изменении условий.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Получатель — коммерческая исследовательская организация. Грант выдан на гражданские прикладные исследования и экспериментальную разработку, без последующего предоставления средств другим лицам. Предусмотрены охраноспособный результат, направление сведений о работах в установленную систему учёта, применимые требования софинансирования выполнены. Срок достижения результата ещё не истёк; рекламный ролик не соответствует цели."},{"case_key":"bank-legal-2026-055","old_hash":"601bd93a5fd526ffddc1cae1e6693ebc","situation":"В Омской области концессионный объект хотят оплатить одновременно полностью из бюджета и через компенсацию тех же затрат инвестору по другому соглашению.\n\nВ финансовой модели одна и та же линия очистки включена в два источника полного возмещения. Инвестор показывает разные наименования затрат, однако заводской номер оборудования совпадает. Общая сумма поддержки превышает подтверждённую стоимость объекта. Перед вами соглашения и финансовая модель; важно проверить движение конкретных расходов до утверждения очередного перечисления.\n\nОдна и та же подтверждённая затрата указана в двух соглашениях, каждое из которых предусматривает полное возмещение этой затраты. Повторное возмещение сверх допустимой стоимости не разрешено; законное софинансирование различных долей или самостоятельных расходов не запрещается. Изменение концессии оформляется по применимому порядку."},{"case_key":"bank-legal-2026-056","old_hash":"836a8d6622f1f6b8bc60bee9f8aa59d0","situation":"В Оренбургской области добывающая компания применяет нефтяной коэффициент к природному газу без проверки специальных правил расчёта НДПИ.\n\nВ добычном отчёте отдельно указаны газ, конденсат и нефть. Бухгалтер взял одну формулу из прежней декларации для всех видов сырья. Технический специалист предупреждает, что показатели добычи и характеристики участков различаются. Участник получает лицензионные сведения и расчёт; решение требует сопоставить каждый вид полезного ископаемого с применимым порядком определения налога.\n\nОктябрь 2026 года; в отчёте отдельно отражены нефть, природный газ (не попутный нефтяной газ) и газовый конденсат. Специальное исключение, разрешающее единый нефтяной расчёт, не установлено."},{"case_key":"bank-legal-2026-057","old_hash":"855533a3d78ac97a56574f8de9372d6e","situation":"В Орловской области заявка на субсидию подана в срок, но комиссия исключила её из-за устного указания перенести приём на день раньше.\n\nЭлектронная система сохранила время приёма заявки до опубликованного окончания отбора. Новая дата отсутствует на официальной странице и в нормативном порядке. Секретарь комиссии предлагает удалить запись как позднюю, чтобы не переделывать протокол. Перед вами извещение, подтверждение отправки и журнал заявок; необходимо определить дальнейшее рассмотрение и документирование решения.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Учебный конкурс проводится по региональному порядку согласно абз. 2 п. 4 ст. 78.5; опубликованный срок не изменялся, окончательный протокол не подписан, заявка своевременна и сохранена."},{"case_key":"bank-legal-2026-058","old_hash":"742aa067d7e6e6cf860ebf60abb1a916","situation":"В Пензенской области субсидия возмещает лизинговые платежи. В заявку включён выкуп объекта и штраф за просрочку, хотя эти затраты не названы допустимыми.\n\nЛизинговый график отделяет плату за пользование, выкупную стоимость и неустойку. Предприятие объединило три суммы в одну строку подтверждённых затрат на оборудование. В соглашении о поддержке описаны допустимые платежи и период возмещения. Участнику нужно сопоставить документы с этими условиями до расчёта субсидии, сохранив возможность объяснить каждое включение и исключение.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Учебный порядок возмещает только подтверждённую плату за пользование оборудованием за установленный период, прямо исключает выкупную цену и неустойку. Получатель не претендует на возмещение иных расходов по этому соглашению; учитывается применимый режим НДС."},{"case_key":"bank-legal-2026-059","old_hash":"3f5a50df364f81dce5ae96ca388e6574","situation":"В Пермском крае регион подписывает инвестиционное соглашение, обещая неизменность местного налога, ставку которого устанавливает муниципальный представительный орган.\n\nИнвестор рассчитывает окупаемость объекта на основании обещанной ставки земельного налога. Муниципальный совет ранее обсуждал её изменение, но не участвовал в подписании регионального соглашения. В письме предприятию обещаны компенсации при любом росте налога. Участник получил соглашение и местный акт; необходимо установить компетенцию участников и пределы принимаемых обязательств.\n\nЗемельный налог установлен действующим актом обычного муниципального образования, а соглашение не относится к специальному предусмотренному федеральным законом режиму стабилизации. В рассматриваемом случае регион не уполномочен фиксировать его ставку и не имеет надлежащего основания обещать компенсацию любого роста."},{"case_key":"bank-legal-2026-060","old_hash":"cf581741cf958c66bad2ce717c638ad8","situation":"В Псковской области мост принадлежит муниципалитету, а регион выделяет средства без определения вида межбюджетного трансферта, цели и условий.\n\nМестный совет подтвердил необходимость ремонта, однако ремонтный контракт ещё не заключён. Регион направляет 20 млн ₽ с формулировкой «на помощь району», без уточнения порядка использования и отчётности. В проекте местного бюджета расход пока не отражён. Участник получает документы собственности, смету и письмо финансиста; нужно определить правовую форму передачи денег до начала работ.\n\nМост принадлежит муниципалитету и ремонт является его собственным расходным обязательством. Для учебного софинансирования применяется субсидия по статье 139 БК РФ; иные трансферты возможны лишь на самостоятельном предусмотренном основании. Передача государственных полномочий здесь не предполагается. Обязательные защитные меры выполняются независимо от ожидания средств."},{"case_key":"bank-legal-2026-061","old_hash":"2d8e2b246187989abfcf260e8da10351","situation":"В Ростовской области заказчик требует в конкурсе, чтобы участник был зарегистрирован только в этом регионе, хотя законного основания ограничения нет.\n\nПоставщики из соседних областей готовы выполнить условия поставки и обслуживания. Заказчик объясняет ограничение заботой о региональной занятости, но предмет закупки не связан с местом регистрации фирмы. Жалоба поступила до окончания приёма заявок. Перед вами извещение и проект документации; требуется определить действие до подведения итогов конкурса.\n\nЗакупка проводится конкурентным способом по 44-ФЗ; требование о местной регистрации не предусмотрено применимой нормой и не связано с предметом закупки. Изменение извещения выполняется по установленному порядку с соблюдением сроков и прав всех участников; жалоба рассматривается компетентным органом."},{"case_key":"bank-legal-2026-062","old_hash":"288be9c4c430b382509ccae2f4c494a1","situation":"В Рязанской области общий отчёт об исполнении бюджета показывает планы вместо кассовых расходов. Пояснение о задержке платежей убрано перед слушаниями.\n\nВ публичной таблице указано 100% освоения по программе, хотя казначейские платежи составили 72% ассигнований. Оставшиеся деньги не ушли из-за непредставленных актов подрядчика. Доклад на слушаниях подготовлен по плановой ведомости.\n\nРечь о дополнительной публичной аналитической таблице к слушаниям, а не об изменении утверждённой формы бюджетной отчётности. На одну и ту же отчётную дату фактические платежи равны 72% утверждённых ассигнований. Обязательные отчёты сохраняются и исправляются в установленном порядке; данные не ограничены в доступе."},{"case_key":"bank-legal-2026-063","old_hash":"5824272987d18a3b06c201db3256fdc1","situation":"В Самарской области организация просит инвестиционный налоговый кредит. Ей предлагают обычную беспроцентную субсидию, называя обе меры одинаковыми.\n\nЗаявитель предлагает модернизировать производство и приложил расчёт будущих платежей. Проект налогового кредита предусматривает срок, проценты и порядок возврата; проект субсидии предусматривает бюджетное перечисление с иными условиями. В служебной записке оба инструмента записаны одной суммой «помощи». Участнику нужно определить различия правовых последствий до выбора механизма и подготовки документов.\n\nОрганизация рассматривает техническое перевооружение собственного производства; обращение относится к региональной части налога на прибыль. Основание, документы, ограничения и согласования ещё не подтверждены; бюджетная субсидия лишь отдельный возможный инструмент."},{"case_key":"bank-legal-2026-064","old_hash":"34a70d9adff9fd9719e52f0b36644262","situation":"В Саратовской области учреждение готовится заключить контракт на будущий год, игнорируя ограничения принятия обязательств и наличие предусмотренного многолетнего основания.\n\nУчреждение хочет зарезервировать оборудование на 24 месяца и договориться о платежах в двух финансовых годах. Текущие лимиты покрывают только первую часть цены. В документах нет решения или иного применимого основания долгосрочного обязательства. Участник получает проект договора и бюджетные показатели; необходимо проверить возможность принятия всего обязательства до подписания.\n\nУчебное условие: заказчик — казённое учреждение, действующее как получатель бюджетных средств.\n\nДоговор не подписан; предполагаются платежи за пределами срока действия доведённых лимитов, а не просто переход в следующий календарный год. Закупка обычная, специального основания превышения срока ЛБО нет. Оборудование необязательное; временное использование существующего имущества допустимо при подтверждённых правах и пригодности."},{"case_key":"bank-legal-2026-065","old_hash":"28f8f90f3d07a08c13a305bcc563eeb9","situation":"Сахалинская область рассчитывает доходы по проекту раздела продукции как по обычной системе НДПИ и налога на прибыль, не проверяя соглашение.\n\nВ соглашении предусмотрены особый порядок учёта продукции, компенсационные расходы и распределение долей. Финансист переносит в прогноз стандартный расчёт по другой добывающей компании. В результате один поток записан сразу в два вида поступлений. Участник получает текст соглашения и ведомость добычи; нужно установить применимую схему и проверить отсутствие двойного счёта доходов.\n\nЭто условное современное соглашение о разделе продукции, отвечающее требованиям специального налогового режима; используется способ раздела по п. 1 ст. 8 закона о соглашениях о разделе продукции. Условия реальных исторических сахалинских проектов не воспроизводятся."},{"case_key":"bank-legal-2026-066","old_hash":"21f7c254eb9fa7620e9b2e146fe4c284","situation":"В Свердловской области имущество казны хотят передать в залог по долгу частного предприятия одним служебным письмом без полномочий и оценки последствий.\n\nПредприятие просит залог склада казны для продления банковского кредита. Оценка объекта и перечень допустимых операций не приложены, а подписант письма не управляет этим имуществом. В случае взыскания регион потеряет используемый склад. Перед вами запрос банка и реестр собственности; требуется определить уполномоченное решение и оценку обязательств до предоставления обеспечения.\n\nСклад находится в составе казны субъекта; правом распоряжения служебный подписант не наделён. Договор залога ещё не заключён. Допустимость обременения проверяется по режиму конкретного объекта, полномочиям собственника и специальным ограничениям; наличие законной государственной преференции не предполагается."},{"case_key":"bank-legal-2026-067","old_hash":"45de65df7f8e2b1dab71079ec2d7010f","situation":"В Смоленской области учреждению предлагают пожертвование с условием закупать товар только у жертвователя по завышенной цене. Условие противоречит цели и процедуре расходования.\n\nДоговор пожертвования предусматривает 2 млн ₽, но связывает использование денег с покупкой по указанной цене. Аналогичный товар другого поставщика стоит существенно дешевле. Учреждение считает, что без бюджетного источника закупочные требования не применяются. Участник изучает условия дара, режим учреждения и предложения рынка до принятия денег и обязательств по их расходованию.\n\nУчебное условие: получатель — бюджетное учреждение; заблаговременно размещённого положения о закупке, позволяющего применить 223-ФЗ к дарам, нет.\n\nПолучатель — бюджетное учреждение. Размещённого до начала года положения о закупке по 223-ФЗ нет; иные исключения не применимы. Допустимое пожертвование в общеполезных целях учитывается обособленно при целевом назначении, но не создаёт права закупать у навязанного поставщика вне применимой процедуры."},{"case_key":"bank-legal-2026-068","old_hash":"0e0880fd3a05b2a51992459d1754ab2a","situation":"В Тамбовской области жители выбрали проект. Администрация подменила его другим объектом без информирования и предусмотренного пересмотра инициативного проекта.\n\nЖители выбрали освещение пешеходного маршрута и собрали подтверждения поддержки проекта. В новом плане администрации вместо него указана площадка у другого здания. Авторы инициативы узнали об изменении из объявления подрядчика. Участнику доступны протокол отбора и проект финансирования; необходимо определить порядок информирования и изменения решения до заключения контракта.\n\nПрименяется установленный муниципальный порядок инициативных проектов по статье 49 закона №33-ФЗ. Проект освещения прошёл предусмотренный отбор; замена объекта ещё не оформлена. Согласование с инициаторами и бюджетное решение проводятся по применимым правилам; инициативные платежи имеют специальный целевой режим и возвращаются в предусмотренных законом случаях."},{"case_key":"bank-legal-2026-069","old_hash":"9cb7d4d8f2cfde1932d517bb1f2eb08f","situation":"В Тверской области гарантия уже выдана и учтена, но при расчёте долговых обязательств её исключают, потому что кредитор ещё не предъявил требование.\n\nГарантия содержит определённый объём ответственности и действует до погашения кредита. Предприятие пока исправно вносит платежи, поэтому финансист предлагает не учитывать риск в долговой книге. Новый заём рассчитывается по уменьшенному показателю нагрузки. Участник получает гарантию и расчёт предельного долга; нужно установить, как учитывать существующее обязательство до решения о заимствовании.\n\nГарантия субъекта РФ действующая, обязательство из неё не прекращено, выражено в рублях; учитывается актуальный объём обязательств, а не обязательно первоначальный максимум."},{"case_key":"bank-legal-2026-070","old_hash":"7f9dc4b6237c75778c806128032b0453","situation":"В Томской области университетский стартап просит бюджетную инвестицию. Организация не определила собственника прав на технологию и основания участия региона.\n\nПрототип создан преподавателями университета и сотрудниками компании по разным соглашениям. В заявке на участие региона указано будущее владение долей, но договоры об интеллектуальных правах не представлены. Оценка стоимости технологии основана на ожиданиях продаж. Участник изучает состав участников и документы прав; необходимо определить подтверждения для решения о бюджетном вложении.\n\nУчебное условие: предполагаемый получатель инвестиции — коммерческое общество, а не сам университет как учреждение.\n\nКоммерческое общество является предполагаемым получателем обычной бюджетной инвестиции по статье 80 БК РФ, без специальных исключений. До решения устанавливаются правообладатели технологии, режим служебных результатов и договоры распоряжения правами. Лицензия не передаёт исключительное право; публичное участие в капитале оформляется в установленном порядке."},{"case_key":"bank-legal-2026-071","old_hash":"2586f7349ac6923152272ddb19f579e0","situation":"В Тульской области поставщик сорвал поставку оборудования. Заказчик прощает неустойку только из-за дружеского письма без предусмотренного законом основания.\n\nОборудование поступило на три недели позже срока, что подтверждается складским журналом. Поставщик сослался на давнее знакомство с руководителем и попросил закрыть вопрос письмом. Юрист не нашёл документов о законном освобождении или списании. Участник получает контракт и даты исполнения; решение касается надлежащего рассмотрения ответственности и фиксации основания выбранного действия.\n\nПо условию учебной истории контракт заключён по результатам конкурентной закупки; обязанность предъявить требование применяется, установленных оснований освобождения или списания нет.\n\nДополнительное учебное условие: оборудование поставлено, но предусмотренная контрактом обязательная наладка ещё не завершена; специальные исключения пункта 2 Правил списания неустоек (постановление Правительства РФ №783) не применяются. После полного исполнения вопрос о списании проверяется повторно.\n\nОбязательная наладка ещё не завершена; оснований освобождения от ответственности и специальных исключений пункта 2 Правил №783 в учебной ситуации нет."},{"case_key":"bank-legal-2026-072","old_hash":"62ec81c0b9e94edfac0eed8e1520fb83","situation":"Тюменская область сводит собственные доходы с доходами автономных округов и публикует итог как доход именно областного бюджета, не консолидированного.\n\nНа слайде для публичного обсуждения отсутствует подпись о составе территории и бюджетов. Читатели сравнивают полученную сумму с доходами отдельного субъекта за прошлый год. В рабочей таблице сведения автономных округов выделены отдельно.\n\nВ задаче используется дополнительный аналитический свод трёх региональных бюджетов: Тюменской области, ХМАО — Югры и ЯНАО, за одинаковый период. Муниципальные бюджеты и внебюджетные фонды в него не входят. Он не обозначается как утверждённый бюджет или предусмотренный ст. 14 БК РФ консолидированный бюджет субъекта; при своде исключаются только трансферты внутри заданного периметра."},{"case_key":"bank-legal-2026-073","old_hash":"3c5a6e2b0e910a45d5548fb990dd4893","situation":"В Ульяновской области авиапредприятию компенсируют затраты на оборудование. Приложенный акт относится к другому юридическому лицу группы.\n\nЗаявитель и владелец оборудования имеют разные идентификационные номера и отдельные договоры. Документ оплаты представлен дочерней организацией, а субсидию просит головная компания. В условиях программы возмещаются затраты конкретного получателя. Участник получает реестр группы и первичные документы; нужно проверить, чьи расходы подтверждены и какой пакет может быть принят.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. По учебному порядку получатель должен сам понести и документально подтвердить затраты; групповые и совместные затраты, расходы по поручению, правопреемство и последующее предоставление средств не предусмотрены. Дочерняя организация приобрела и оплатила оборудование от собственного имени, головная его не оплачивала."},{"case_key":"bank-legal-2026-074","old_hash":"9946e63deca6f3ca8183f5062f688f44","situation":"В Челябинской области проект реконструкции бюджетного объекта изменён так, что выросла стоимость. Получатель просит перечислить превышение без изменения бюджетного решения.\n\nПроектировщик добавил новый корпус и изменил технические решения после экспертизы. Подрядчик представил дополнительную смету на 16 млн ₽ сверх первоначального обеспечения. В казначейство направлена заявка по прежнему объекту и цене. Перед вами версии проекта и финансовое решение; необходимо определить последовательность оформления изменений до перечисления увеличенной суммы.\n\nОбъект относится к публичной собственности; применяется обычный режим бюджетных инвестиций по статье 79, а контракт заключён по 44-ФЗ. Добавленный корпус не утверждён в инвестиционном решении, дополнительные ассигнования отсутствуют. Необходимость повторной экспертизы и допустимость изменения контракта устанавливаются по применимым нормам до принятия обязательства."},{"case_key":"bank-legal-2026-075","old_hash":"880cd55fe953afba04acef0c6cfb9ca5","situation":"В Забайкальском крае компенсацию проживания для работников предлагают обложить НДФЛ как зарплату без проверки установленной законом льготы и характера выплаты.\n\nРаботодатель оплатил жильё работникам по отдельной программе переезда и включил платежи в общий зарплатный регистр. В трудовых документах отражено основание предоставления жилья, но бухгалтер не проверил категорию выплаты. Работники запросили расчёт удержания. Участник сопоставляет документы программы, выплаты и применимые условия налогообложения до формирования отчётности.\n\nСуществующие работники по предварительной договорённости переезжают на работу в другую местность. Отдельно документируются расходы на переезд и обустройство по ст. 169 ТК РФ, отдельно — самостоятельная регулярная оплата жилья работодателем; последняя автоматически не признаётся компенсацией переезда."},{"case_key":"bank-legal-2026-076","old_hash":"0d2b952f7ea3afee23b5858869867b6a","situation":"В Ярославской области сбор за размещение вывески назван налогом и вводится письмом департамента. В НК такой налог не предусмотрен.\n\nПисьмо устанавливает ежемесячный платёж для всех владельцев вывесок без договора об услуге. В акте отсутствуют налоговая база, плательщики и законное основание нового налога. Предпринимателю угрожают отказом в согласовании вывески при неоплате. Участник получает письмо и документы размещения; необходимо определить природу требования и порядок действий по конкретному заявлению.\n\nПлатёж обязателен по одному лишь письму департамента, не предусмотрен НК РФ и не является установленной законом пошлиной, платой за специальное право или добровольной услугой. Дополнительные услуги, если они предлагаются, реально оказываются на добровольной основе без влияния на выдачу согласования. Правила размещения и контроль безопасности возможны исключительно в рамках имеющихся полномочий и действующих требований."},{"case_key":"bank-legal-2026-077","old_hash":"8e2bac492972a62cb572126d420c80eb","situation":"В Москве предприниматель рассчитывает торговый сбор по площади всего здания, хотя использует отдельный объект торговли и должен учитывать конкретную категорию.\n\nТорговый зал занимает 80 м² в здании площадью 900 м², где есть офисы и склад другого арендатора. В расчёт перенесена площадь всей недвижимости из общей выписки. Вид и расположение торгового объекта подтверждены договором. Участник получает план помещений и сведения об использовании; требуется проверить выбранную категорию и соответствующие параметры расчёта сбора.\n\nОбъект — розничная торговля через стационарную торговую сеть с торговым залом в Москве. 80 м² включают всю соответствующую площадь обслуживания и торговли; 820 м² здания используются отдельно другими лицами и не относятся к объекту. Льгота не установлена."},{"case_key":"bank-legal-2026-078","old_hash":"e1392e8b7973ff3953e9ba4c45adcbbf","situation":"В Санкт-Петербурге бюджетное финансирование реставрации предлагают выдать собственнику без обязательств по сохранению объекта культурного наследия и контролю результата.\n\nЗдание находится в частной собственности и включено в перечень охраняемых объектов. Смета предусматривает реставрацию фасада, но проект соглашения не определяет содержание результата и последующий контроль. Собственник намерен менять элементы декора по своему проекту. Перед вами охранные документы и смета; нужно оценить условия передачи денег и исполнения обязательств по сохранению объекта.\n\nЗдание включено в реестр объектов культурного наследия; собственник несёт обязанности по его содержанию. Для конкретных реставрационных работ необходимы предусмотренные заданием, разрешением, согласованной документацией и надзором условия; исполнитель имеет требуемую лицензию, если она обязательна. Субсидия предоставляется по самостоятельному установленному порядку."},{"case_key":"bank-legal-2026-079","old_hash":"e9dde550802ad7a830c0da1f70cea6cc","situation":"В Еврейской автономной области платёж оформляют на основании неподписанного акта выполненных работ. Получатель уверяет, что подпись появится после перечисления.\n\nПодрядчик приложил неподписанный акт и фотографии, часть которых относится к другому помещению. Ответственный за приёмку ещё не осмотрел выполненные работы. Бухгалтер готовит платёж, чтобы успеть до конца месяца. Участник получает контракт, акт и материалы осмотра; необходимо определить подтверждённость исполнения и дальнейшие документы до перечисления средств.\n\nПо условию учебной истории учреждение уже использует защищённую систему с готовым маршрутом согласования документов; расширение системы и закупка не нужны.\n\nУчебное условие: заказчик — казённое учреждение, контракт заключён по 44-ФЗ.\n\nОбычный контракт на ремонт по результатам открытой электронной процедуры; оплата после приёмки результата или предусмотренного контрактом отдельного этапа, аванс не предусмотрен. Требования экспертизы и применимые сроки приёмки обязательны."},{"case_key":"bank-legal-2026-080","old_hash":"a07a2aa9c0fd002e396b28e38aee4e98","situation":"В Ненецком автономном округе местному бюджету обещают определённую долю дохода, но не оформляют предусмотренный акт о дополнительном нормативе отчисления.\n\nВ бюджетном проекте поселения доля налога включена как уже действующий норматив. Региональный представитель обсуждал её на совещании, но акт не опубликован. Объём расходов сформирован под ожидаемый доход. Участник изучает действующие нормативы и протокол совещания; нужно определить правовое основание изменения и корректный момент отражения поступления в плане.\n\nПо условию учебной истории обсуждается норматив отчислений, который должен быть установлен законом субъекта Российской Федерации; муниципальный район не устанавливает этот региональный норматив самостоятельно.\n\nВ учебной ситуации предлагается норматив отчислений, устанавливаемый именно законом субъекта по применимому положению статьи 58 БК РФ. Вид налога и муниципального образования проверены; специальное временное исключение не предполагается. До вступления акта в силу предлагаемая доля показывается как сценарий, а не действующий норматив."},{"case_key":"bank-legal-2026-081","old_hash":"b1c5067da236467b71778c39c9d6e594","situation":"В Югре соглашение о субсидии подписано. Сотрудник позже требует новые обязательства получателя, которых нет в соглашении и нормативном порядке.\n\nПолучатель выполняет согласованные показатели и представил промежуточный отчёт. В новом письме ведомство добавило требования к числу работников, которых не было при заключении соглашения. За отказ обещают приостановить платёж. Участник получает обе версии условий и документы отбора; требуется оценить допустимость изменения и порядок рассмотрения позиции получателя.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Учебная программа финансирует текущие затраты; применимый нормативный порядок и законодательство не изменились, лимиты не сокращены, иных оснований обязательного изменения или приостановления нет. Новые требования содержатся только в письме сотрудника."},{"case_key":"bank-legal-2026-082","old_hash":"10e2977fdfc299d0e1481e057732d66c","situation":"На Чукотке средства на северный завоз предлагается перечислить организации без проверки включения расходов в план завоза и подтверждения поставки.\n\nПоставка должна пройти по отдельному календарю до закрытия навигации. В заявке объединены основные товары завоза и коммерческая партия оборудования, не включённая в утверждённый план. Накладные подтверждают только часть груза. Участник изучает план, договор и перевозочные документы; нужно установить объём допустимого финансирования и необходимые подтверждения до платежа.\n\nУчебный план северного завоза утверждён федеральным координатором; коммерческая партия не входит в финансируемый перечень. Право на средства устанавливается отдельным договором и условиями поддержки. Приоритет перевозки определяется установленными категориями грузов, не является универсальным правом на бюджетную оплату."},{"case_key":"bank-legal-2026-083","old_hash":"2e2fad9909881fbd87a00c18c27c6db8","situation":"На Ямале имущество получателя субсидии арестовано, но он просит перечислить деньги на счёт другой фирмы, не указанной в соглашении.\n\nВ соглашении определены конкретный получатель и его обязанности по отчёту. Новая фирма предлагает принять деньги и рассчитаться с подрядчиком, но не входит в договорные отношения. Получатель объясняет смену счёта исполнительными ограничениями. Перед вами реквизиты, соглашение и сведения об ограничении; необходимо определить допустимость перечисления и предусмотренный порядок дальнейших действий.\n\nУчебная программа из бюджета субъекта РФ; получатель — коммерческое юридическое лицо, не государственное или муниципальное учреждение; применим пп. 2 п. 2 ст. 78 БК РФ и общие требования постановления Правительства РФ от 25.10.2023 №1782. Специальные исключения, в том числе последующее предоставление средств иным лицам, отсутствуют. Учебная субсидия предназначена действующему получателю и не содержит разрешения на перечисление третьей фирме; казначейское сопровождение и вид исполнительного ограничения ещё уточняются.\n\nУчебная субсидия имеет конкретного получателя, соглашение не допускает платёж третьей фирме. Вид исполнительного ограничения проверяется компетентным органом; смена получателя не служит обходом ареста. Применимость казначейского сопровождения и правомерного правопреемства устанавливается отдельно, не предполагается."},{"case_key":"bank-legal-2026-084","old_hash":"cdebe52fa57e4782d092c16f6e971c01","situation":"В условном муниципальном образовании Республики Крым объект размещения не внесён в надлежащий реестр. Муниципалитет автоматически считает отсутствие записи освобождением от любого налогового обязательства.\n\nГостиница фактически размещает гостей и отражает доходы, а заявка на включение в реестр находится на рассмотрении. В служебной записке смешаны условия конкретного налога и отсутствие любых обязанностей бизнеса. Администратор просит отменить все расчёты. Участник получает документы объекта, период деятельности и налоговые регистры; необходимо отдельно проверить применимость каждого обязательства.\n\nДействие учебной истории — 2026 год. По условиям вымышленной задачи в данном муниципалитете на рассматриваемый период туристический налог не введён. Это не утверждение о всех муниципалитетах Республики Крым.\n\nУсловия игры применяют российскую налоговую модель; не утверждается фактическое состояние местных актов на спорной территории. В заданном муниципалитете в 2026 году нет вступившего в силу акта о туристическом налоге. Наличие или отсутствие записи в реестре не отменяет остальные налоговые обязанности. Для муниципалитета, где налог введён, отдельно проверяется специальный порядок п. 3 ст. 418.3: направление сведений уполномоченным органом и их размещение на официальном сайте. Обмен данными допускается по законному основанию и с защитой сведений."},{"case_key":"bank-legal-2026-085","old_hash":"c36588e36541a88b1442293367fa7217","situation":"В Севастополе участок передан организации в безвозмездное пользование. Бухгалтер начисляет земельный налог как при собственности без проверки объекта и плательщика.\n\nДоговор устанавливает срок пользования и порядок возврата участка без передачи собственности. Выписка подтверждает другого собственника, а налоговый расчёт составлен по общей карточке имущества организации. Бухгалтеру требуется ответ до платежа. Участник получает договор и выписку; нужно установить статус пользователя и применимые условия признания плательщиком, а не исходить из самого факта нахождения на земле.\n\nРассматривается применение российской правовой модели в вымышленной учебной истории. Организация имеет только право безвозмездного пользования данным участком, не собственность, не постоянное бессрочное пользование и не другое предусмотренное ст. 388 право. Не является управляющей компанией соответствующего ПИФ."},{"case_key":"bank-legal-2026-086","old_hash":"1ac532afe3d0b999beac63ca91b2ab60","situation":"В Донецкой Народной Республике выделена целевая помощь на восстановление водоснабжения. Смета включает мебель администрации, не связанную с проектом.\n\nВ соглашении определены насосная станция, трубы и контроль восстановления подачи воды. Позиция о мебели появилась в последней версии сметы без изменения цели помощи. На неё предусмотрено 1,2 млн ₽. Участник сравнивает версии сметы и перечень результатов; необходимо проверить связь конкретной затраты с соглашением до утверждения финансирования.\n\nЦель учебного целевого трансферта — насосная станция, трубы и контроль восстановления подачи воды. Мебель администрации не входит в утверждённую цель; законного изменения соглашения нет. Отдельная потребность в мебели при наличии основания финансируется из другого источника."},{"case_key":"bank-legal-2026-087","old_hash":"bd0035bb47f5b1e91e18297a90e1651a","situation":"В Луганской Народной Республике организация применяет обычную налоговую норму, не проверив предусмотренное переходное регулирование по периоду и статусу.\n\nВ досье отражены дата регистрации организации, период операции и начало применения отдельных норм. Бухгалтер скопировал расчёт компании из другого субъекта, не учитывая эти даты. Документы о статусе получены до сдачи отчётности. Участник сопоставляет период, территориальные правила и конкретную операцию; выбор должен опираться на действующее для этого случая регулирование.\n\nЭто ретроспективная учебная ситуация: рассматривается отчётный период, начавшийся 1 января 2023 года; организация соответствует условию места нахождения по статье 11 443-ФЗ. Бухгалтер ошибочно считает допустимым только электронный способ подачи декларации. Норма разрешала бумажную форму для указанного периода; она не устанавливает такую возможность для 2026 года.\n\nПроверяется только историческая норма о форме представления отчётности за период, начавшийся 01.01.2023, при наличии установленного законом места нахождения исполнительного органа на соответствующую дату. В игровой задаче применяется российская правовая модель. Никакие выводы о применимости иных переходных норм, продлениях срока по ч. 2 ст. 11 или правилах подачи за периоды 2026 года не делаются. Корректность суммы проверяется отдельно."},{"case_key":"bank-legal-2026-088","old_hash":"a54ffef48c1a2faa2a8d5d90006ecfe7","situation":"В Херсонской области переданное государственное полномочие расширяют, но размер субвенции и норматив затрат не пересматривают.\n\nОрган получает дополнительные заявления по расширенному перечню услуг, но финансирование рассчитано на прежний объём. Исполнители предлагают сократить сроки других обязательных работ, чтобы уложиться в сумму. В проекте передачи полномочия отсутствует новый расчёт затрат. Участник получает перечень функций и норматив расходов; необходимо определить порядок финансового обеспечения изменённого объёма.\n\nВ этой истории регион передал исполнение полномочия муниципальному образованию и перечисляет ему субвенцию из своего бюджета. Проверяется именно этот межбюджетный маршрут.\n\nВ рамках российской правовой модели учебной игры речь идёт о проекте изменения регионального закона о переданном государственном полномочии, а не о уже вступившем в силу расширении. Применимая методика содержит расчёт затрат, который должен быть актуализирован для нового объёма функций. До законного вступления изменений в силу сохраняются действующие обязательные услуги."},{"case_key":"bank-legal-2026-089","old_hash":"38c1af85cc7c67ef7939647b35f61660","situation":"В Запорожской области финансируют восстановление объекта, не установив собственника, получателя и законное основание бюджетной инвестиции.\n\nВосстанавливаемый объект числится в нескольких старых реестрах с различными сведениями о владельце. Организация предлагает принять средства как будущий оператор, но её права не оформлены. Проект предусматривает капитальные вложения, а не текущую услугу. Перед вами выписки и смета; необходимо установить законного получателя, объект и основание вложения до принятия обязательства.\n\nВ учебной модели предполагаются капитальные вложения; документы о принадлежности объекта и полномочиях получателя пока противоречивы. Будущий оператор не приобретает права на средства только по заявлению."},{"case_key":"bank-legal-2026-095","old_hash":"04d8f0440393c402c287cc657f51cf0c","situation":"Президент отклонил федеральный закон и направил палатам мотивированные возражения. Фракция Государственной Думы намерена сохранить прежний текст. Её руководитель предлагает повторно проголосовать простым большинством депутатов и направить закон Президенту, не рассматривая его в Совете Федерации: первая стадия в верхней палате уже была пройдена. Юрист получил протокол первоначального голосования и проект нового постановления. Речь идёт о преодолении президентского отклонения в ранее принятой редакции, а не о новом согласованном тексте. Какую политико-организационную стратегию рекомендовать, не меняя конституционного порядка принятия закона?\n\nРечь об обычном федеральном законе, отклонённом Президентом в смысле части 3 статьи 107 Конституции, а не о возврате без рассмотрения из-за нарушенной процедуры. Палаты действуют по установленным регламентам; политическая пауза допускается только без нарушения обязательных сроков."},{"case_key":"bank-legal-2026-102","old_hash":"c7fd7b84e3ee00f42d29adc559d6b4fd","situation":"Председатель закупочной комиссии обнаружил среди участников конкурса компанию своей супруги. Он не владеет её долей, но семейный доход зависит от результата закупки. До заседания руководитель предлагает ему «просто молчать»: председатель останется в составе комиссии и проголосует, не комментируя заявку. Остальные члены о связи не знают. Закупка проводится по №44-ФЗ. При такой заинтересованности член комиссии обязан незамедлительно уведомить заказчика, сформировавшего комиссию; заказчик обязан незамедлительно заменить его. После обязательной замены заинтересованного члена решением заказчика какую дополнительную меру организации отбора и предупреждения повторных конфликтов выбрать?"},{"case_key":"bank-legal-2026-106","old_hash":"f92c751a283b4308bafb5b41dd36b076","situation":"Участник закупки по №44-ФЗ обнаружил спорное условие документации уже после того, как истёк применимый срок административной жалобы и был заключён контракт. Он направил в контрольный орган письмо с требованием немедленно отменить договор. Юрист участника предлагает обсудить судебную защиту, но директор считает, что любое письмо автоматически останавливает исполнение. В досье нет решения суда или уполномоченного органа об ограничительных мерах. Какую рекомендательную меру поддержки законной защиты и предупреждения новых закупочных споров выбрать, не вмешиваясь в действующий контракт?"},{"case_key":"bank-legal-2026-147","old_hash":"ff48c68f2a6f882ed65f4c176073c40d","situation":"Для доставки материалов при чрезвычайной ситуации орган изъял грузовой автомобиль частного владельца. В акте он исключил оценку стоимости, компенсацию и последующий возврат. Срочные работы закончены, автомобиль сохранился; собственник просит сообщить его состояние и основание дальнейшего удержания. Спор об оценке ещё не рассмотрен. После установления законного основания, исполнения обязательных гарантий и прекращения необоснованного удержания какую дополнительную меру урегулирования и профилактики выбрать?\n\nУчебный эпизод касается реквизиции по статье 242 ГК РФ, не конфискации, не транспортной мобилизации и не специальной процедуре изъятия. Применимый чрезвычайный режим и полномочие государственного органа установлены в условии."},{"case_key":"budget-region-2026-05-essential-services-gap","old_hash":"470cff8a56b7725c81b4e29e198d42fd","situation":"В Республике Дагестан сокращение заказов у действующих предприятий привело к падению прибыли. Региональный прогноз выявил трёхмесячную просрочку обязательных выплат учреждениям. Регион просит дотацию на поддержку мер по обеспечению сбалансированности бюджета в размере 420 млн ₽ для закрытия временного разрыва; расчёт выделяет выплаты образованию, здравоохранению и коммунальным учреждениям. Запрашиваемая дотация общего характера, 420 млн ₽, полностью покрывает общую смету в 420 млн ₽. Отдельное софинансирование не предусмотрено. В проекте федерального бюджета пока рассматривают эту потребность; решения о выделении денег и самого перечисления ещё нет.\n\nПодтверждённые обязательства по оплате не прекращаются. 420 млн ₽ — расчёт непокрытой потребности, а не размер дотации по федеральной методике. Сумма не считается поступившим доходом. Условия возможной дотации, включая контроль их выполнения, соблюдаются."},{"case_key":"budget-region-2026-10-hospital-equipment","old_hash":"665a991d456fd56ef0e85dc6a56503c8","situation":"В Республике Карелия два диагностических аппарата районной больницы выведены из эксплуатации. Жители удалённых поселений ожидают обследование в среднем 60 дней. Регион предлагает обновить диагностический блок, организовать выездные приёмы и обучить персонал работе с оборудованием. Диагностический блок, выездные приёмы и обучение оценены вместе в 675 млн ₽: регион просит 540 млн ₽ из федерального бюджета и заявляет 135 млн ₽ своих средств. Этот расчёт представлен к проекту федерального бюджета, деньги ещё не выделены и не перечислены.\n\nБольница — государственная медицинская организация субъекта, а предлагаемое оснащение, аренда, выезды и обучение включаются в заявку лишь в части допустимых расходов. Медицинские маршруты и срочность устанавливают уполномоченные медицинские работники; обязательная помощь сохраняется вне зависимости от выбора. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-14-credit","old_hash":"101d841d7b815cb9ab62c3b3afbde49f","situation":"Республика Саха (Якутия) запрашивает бюджетный кредит 2 400 млн ₽ на кассовый разрыв во время северного завоза. График подтвержденного возврата опирается на поступления следующих кварталов. В опубликованной презентации сумму ошибочно назвали безвозвратной дотацией и исключили из долга; финансовый орган уже подготовил проект долговой записи и проект соглашения; деньги ещё не поступили и фактический основной долг по новому кредиту пока не возник. Перевозчики ждут оплату, поэтому команда должна определить правовую форму, способ отражения поступления и график возврата. Своевременный завоз сохраняет работу нескольких предприятий; ошибка учёта затрудняет следующий заём.\n\nЗапрашивается обычный федеральный бюджетный кредит бюджету субъекта по статье 93.3 БК РФ, не кредит на пополнение остатка единого счёта по статье 93.6. Условия предоставления, наличие бюджетных средств, отсутствие препятствующей просрочки, соглашение и график возврата проверяются до привлечения; невыбранная сумма не считается полученным долгом."},{"case_key":"budget-region-2026-22-drought-irrigation","old_hash":"d0ca545c5fefc4dc92336dac7b611144","situation":"В Алтайском крае засуха снизила долю продуктивных посевных площадей до 42%. Тридцать небольших хозяйств приостановили деятельность. Регион предлагает восстановить водоснабжение полей, обеспечить повторный посев и техническое сопровождение хозяйств; перечень получателей и площадей приложен к заявке. На восстановление посевных площадей запланировано 700 млн ₽. Заявка к проекту федерального бюджета составляет 560 млн ₽ при заявленной доле региона 140 млн ₽. Хозяйства пока не получили этих денег: заявка ещё не стала решением о финансировании.\n\nОбщие оросительные объекты и помощь хозяйствам разграничены по принадлежности объектов и основаниям расходов; для поддержки хозяйств необходим отдельный установленный порядок, подтверждение критериев и потерь. Не предполагается право всех хозяйств на одинаковую выплату. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-25-bridge-detour","old_hash":"a6f3b9062e387c01c5d1fce1fc5061c2","situation":"В Приморском крае обследование выявило повреждение опор автомобильного моста. После ограничения движения грузовой маршрут удлинился до 72 км, а восемь небольших перевозчиков приостановили работу. Для восстановления прямого сообщения регион представил расчёт ремонта моста и подходов. Ремонт моста и подходов оценён в 1800 млн ₽. Из них 1440 млн ₽ регион запрашивает при рассмотрении проекта федерального бюджета, а 360 млн ₽ заявляет как собственные средства. Федеральную часть ещё не выделили и не перечислили.\n\nМост относится к дороге регионального значения; ограничение введено компетентным владельцем по установленному порядку. Безопасность и информирование об объезде обеспечены. Помощь перевозчикам рассматривается только как отдельная законная мера, не как произвольный расход дорожной субсидии. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-27-delegated","old_hash":"a33574b2a27369becf870270bf3af21e","situation":"Хабаровский край получил проект расчета субвенции на исполнение переданного федерального полномочия. В одном муниципальном реестре 240 получателей услуги повторно включены в две категории; во втором не учтены 60 новых уникальных получателей, по которым обращения проверены и право на услугу подтверждено. Методика предусматривает единый норматив затрат на получателя и сверку исходных сведений. Исполнительный орган предлагает сначала получить всю завышенную сумму, а таблицу исправить после перечисления. Сотрудники муниципалитетов предупреждают, что итоговый отчет невозможно свести.\n\nДля учебного расчёта установлено: каждый из 240 получателей учтён ровно дважды, 60 иных получателей не включены вовсе; применяется заданный единый норматив на уникального получателя. Федеральное полномочие передано в установленном порядке; утверждённая методика требует устранить дубли до направления расчёта. Право на услуги не зависит от участия в выбранной дополнительной мере. Данные обрабатываются только уполномоченными органами в рамках законного основания, без избыточного раскрытия; новый межведомственный обмен не запускается до подтверждения основания, целей и мер защиты."},{"case_key":"budget-region-2026-38-emergency","old_hash":"acf1ce4ea28e73712abd85347f24a943","situation":"В Иркутской области паводок повредил коммунальную инфраструктуру. Регион запросил 600 млн ₽ на подтвержденные неотложные восстановительные работы с актами обследования. Одновременно в заявку добавили строительство нового туристического центра, который не пострадал и отсутствует в аварийных актах. Правительство Иркутской области располагает ограниченными ассигнованиями своего резервного фонда, а перечень работ нужно утвердить до оплаты. Команда должна отделить чрезвычайные расходы от обычного инвестиционного проекта, проверить основания использования резервного фонда и оформить необходимые изменения. Восстановление сетей возвращает действующие предприятия к работе.\n\nУчебное условие: действующий порядок использования соответствующего резервного фонда не предусматривает финансирование указанного нового туристического центра по иному основанию.\n\nДля вымышленной ситуации задан региональный характер ЧС, подтверждённый компетентным органом, и региональный порядок фонда, допускающий перечисленные неотложные работы при надлежащем обосновании. Запрошенные 600 млн ₽ не равны уже утверждённой сумме. Обязательные меры защиты населения выполняются независимо от выбора дополнительной организации работ. Временные технические меры для функционирования бизнеса допустимы только при подтверждённой связи с ликвидацией последствий и отдельном законном основании; обычная помощь компаниям не оплачивается из резерва автоматически. Закупочные и бюджетные требования сохраняются."},{"case_key":"budget-region-2026-38-forest-recovery","old_hash":"b259d6191b69c4f7db36fd960252ea12","situation":"В Иркутской области лесной пожар затронул 2 400 га территории рядом с несколькими населёнными пунктами. Огонь локализован, но остались загрязнённые участки, опасные деревья и нарушенные подъезды. Регион представил расчёт обследования, очистки, восстановления почв и длительного наблюдения. Смета работ после пожара составляет 1100 млн ₽. В проект федерального бюджета направлена заявка на 880 млн ₽, регион заявляет ещё 220 млн ₽ собственных средств. Ни выделения федеральной помощи, ни её перечисления пока не было.\n\nРечь идёт о лесных участках, по которым установлены категории, ответственные лица и публичные полномочия; финансирование касается только законных публичных обязательств, не замещает без основания обязанности лесопользователей. Способ восстановления устанавливается после обследования по лесоводственным требованиям. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-39-credit-return","old_hash":"3e8adb1bbca04241103022989a16c3c1","situation":"По действующему договору обычного федерального бюджетного кредита Калининградская область должна вернуть 850 млн ₽ основного долга в конце финансового периода. Это не кредит на пополнение остатка единого счёта и не специальный инфраструктурный кредит. Соглашение действует, письменного решения о реструктуризации нет. В переписке посредник утверждает, что срок «точно продлят», и предлагает не закладывать платеж, направив остаток на новую закупку. Финансовый орган подготовил два расчета: своевременное погашение и законное обращение о пересмотре условий, которое еще не рассмотрено."},{"case_key":"budget-region-2026-40-industrial-grid","old_hash":"7f8b959e4c299d5e1294a136c3dea863","situation":"В Калужской области восемь новых предприятий работают на промышленной площадке с временным электроснабжением. Эти восемь предприятий ещё не включены в сохранённую начальную базу. Ещё двадцать участков нельзя подключить к постоянным сетям. Регион просит финансирование подъездной дороги, инженерной инфраструктуры и проверки готовности подключения. Для дороги и сетей составлена смета на 1000 млн ₽. Регион просит включить 800 млн ₽ в проект федерального бюджета и заявляет 200 млн ₽ своих средств. Заявка находится на рассмотрении; федеральные деньги ещё не выделены и не поступили.\n\nВ приложении сетевой организации указаны точка присоединения, граница балансовой принадлежности и распределение работ. В региональную заявку предлагают включить также внутренние кабели частных резидентов.\n\nПубличный проект касается общей дороги и сетевой инфраструктуры, находящейся в сфере компетенции соответствующего заказчика. Работы сетевой организации и заявителей распределяются по договорам и техническим условиям; внутренние кабели частных резидентов не включаются автоматически в бюджетную смету. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-42-employment-retraining","old_hash":"2cf99d520ebab5b9f819a078f8c4b7f9","situation":"В Кемеровской области — Кузбассе спад заказов оставил 1 200 работников без устойчивой занятости; десять небольших предприятий приостановили работу. Регион подготовил программу переобучения и трудоустройства для 700 участников с проверкой договорённостей с работодателями. Программа рассчитана на 600 млн ₽: заявленная региональная доля составляет 120 млн ₽, а в проекте федерального бюджета просят предусмотреть 480 млн ₽. Финансирование пока не утверждено, перечислений по заявке не было.\n\nВ учебной выборке 700 человек признаны безработными и соответствуют основаниям направления на обучение по ст. 30; остальные работники рассматриваются по отдельным применимым программам. Направление оформляет служба занятости, программы соответствуют утверждённому перечню востребованных профессий; практика оформляется безопасно. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-43-rural-cultural-centres","old_hash":"085c55179a5cdf415d279008ebb27569","situation":"В Кировской области пять сельских культурных центров ограничили работу из-за состояния помещений и оборудования. Регион представил проект ремонта, доступности для маломобильных посетителей и обновления оборудования; каждому объекту соответствует дефектная ведомость. Пять объектов требуют по общей смете 200 млн ₽. Регион заявляет 40 млн ₽ своих средств и просит 160 млн ₽ в рамках рассмотрения проекта федерального бюджета. Это пока расчёт потребности: федеральную часть не выделили и не перечислили.\n\nПять объектов — муниципальные учреждения культуры; региональное участие оформляется в пределах компетенции и допустимого межбюджетного финансирования. Требования безопасности и доступности соблюдаются, включая временные способы предоставления услуг. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-45-rural-broadband","old_hash":"fb74fd3a5c2eae9684e6b4bd7188bd5a","situation":"В Курганской области восемнадцать населённых пунктов не имеют устойчивого широкополосного доступа. Местные предприниматели не могут регулярно передавать заказы, а социальные учреждения используют нестабильные каналы. Регион подготовил трассировку сети и список точек подключения. Прокладка сети и подключение точек оценены в 450 млн ₽. Из этой суммы 360 млн ₽ запрошены к проекту федерального бюджета, 90 млн ₽ регион заявляет как собственное участие. Средства по заявке пока не выделены и не перечислены.\n\nСеть рассматривается как самостоятельный проект региональной инфраструктуры с подтверждёнными полномочиями. Универсальные услуги связи по ст. 57–58 и договоры оператора проверяются отдельно; для 18 поселений не предполагается автоматически наличие одного и того же федерального права на конкретную скорость или технологию. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-47-food-logistics","old_hash":"79fb164e2936f3c51ab27e07f1e61c5d","situation":"В Ленинградской области десять небольших производителей уже начали работу, но из-за нехватки холодного хранения теряют 22% скоропортящейся продукции. Регион предлагает создать общий логистический узел, подъезд и систему учёта поставок. Эти десять производителей ещё не включены в сохранённую начальную базу; склад ещё не построен. Логистический проект стоит 700 млн ₽. Для него регион заявляет 140 млн ₽ своих средств, ещё 560 млн ₽ просит учесть в проекте федерального бюджета. Федеральное финансирование остаётся заявкой: решения о выделении и перечисления денег пока нет.\n\nЛогистический узел проектируется как публичная инфраструктура для нескольких производителей. Один крупный поставщик просит преимущественное бронирование всех холодильных камер. Остальные предприятия готовы пользоваться складом по опубликованным единым условиям. Помимо сметы нужно определить доступ и порядок распределения ограниченной мощности.\n\nУзел является публичным инфраструктурным проектом с едиными опубликованными условиями доступа. Аренда, кооперация и строительство возможны по отдельным законным договорам; выбор поставщика и доступ производителей не создают необоснованных преимуществ. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-54-cluster","old_hash":"137475d04d4e4caf16b57513eda4ab12","situation":"Новосибирская область готовит запрос на федеральную субсидию 1 800 млн ₽ для инженерной инфраструктуры промышленного кластера. Региональные ассигнования составляют 400 млн ₽. В проекте соглашения указаны публичные сети и число подключенных предприятий, но в приложенном платежном поручении получателем всей межбюджетной суммы назван один коммерческий резидент. Резидент предлагает сам выбрать остальные площадки без конкурсных правил. До запуска ожидаются 18 новых предприятий; без подключения площадки останутся пустыми.\n\nВ учебной ситуации 1 800 млн ₽ — запрашиваемая, ещё не предоставленная федеральная субсидия бюджету субъекта; 400 млн ₽ — региональные ассигнования. Сети создаются как публичная инфраструктура по соглашению, проект которого ещё согласуется. Ожидаемые 18 предприятий — прогноз. Самостоятельная поддержка компаний не входит в цель указанной межбюджетной субсидии; если предлагается отдельная субсидия, для неё необходимы самостоятельные ассигнования, нормативный порядок и предусмотренный отбор, без заранее выбранного резидента. Специальные исключения из общего порядка и прямое определение получателя не заданы."},{"case_key":"budget-region-2026-54-school-capacity","old_hash":"2f53019c46bc2b94795cd3546552bc31","situation":"В Новосибирской области 900 школьников учатся во вторую смену. В новом жилом квартале нет свободных мест; обследование подтверждает, что пристройка к действующей школе не решит проблему. Регион представил проект школы на 600 мест, земельный участок и предварительное подключение к сетям. Строительство оценено в 1200 млн ₽, включая заявленные 240 млн ₽ региона. На остальные 960 млн ₽ подана заявка к проекту федерального бюджета; её рассмотрение ещё не завершилось выделением или перечислением средств.\n\nШкола планируется как муниципальная общеобразовательная организация. Финансирование региональных гарантий образовательного процесса и строительство здания разграничиваются; регион и муниципалитет действуют в пределах своих полномочий. Перераспределение мест и подвоз не отменяют доступность и безопасность обучения. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-56-flood-drainage","old_hash":"c3538e94fa08eb1b16cbae1ac90d59fa","situation":"В Оренбургской области паводок выявил недостаточную пропускную способность водоотводов: 900 домов остаются в зоне повторного подтопления. Двенадцать небольших предприятий приостановили работу. Регион просит профинансировать восстановление водоотводов, берегоукрепление и систему предупреждения. Защитные работы оценены в 1350 млн ₽. Регион заявляет 270 млн ₽ собственного участия и запрашивает 1080 млн ₽ при рассмотрении проекта федерального бюджета. Федеральная часть пока не выделена и не перечислена.\n\nУстановлены региональные и муниципальные полномочия по защите территории, а проект постоянных сооружений относится к соответствующим расходным обязательствам. Не предполагается автоматическое введение режима ЧС или специальной закупки; текущие обязательные защитные меры обеспечиваются независимо от проекта. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-59-heating-network","old_hash":"0bfcea53c2f6a497f96643b68d2ddb33","situation":"В Пермском крае обследование выявило 12 аварийных участков тепловой сети. Перебои затрагивают жилые дома, мастерские и два учреждения образования. Регион подготовил проект замены труб, установки контроля утечек и восстановления покрытий после работ. Замена аварийных участков и сопутствующие работы стоят по смете 900 млн ₽. Регион просит 720 млн ₽ к проекту федерального бюджета, заявляя свои 180 млн ₽. Пока рассматривается заявка; выделенных и перечисленных федеральных средств ещё нет.\n\nСеть находится в муниципальной системе теплоснабжения, ответственная организация и владелец определены; региональная заявка не заменяет их обязанностей. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-63-technical-college","old_hash":"8a3a84ffae7823dce368f42e7882bc92","situation":"В Самарской области двенадцать новых небольших предприятий уже зарегистрированы и начали работу, но им не хватает технических специалистов. Колледж предлагает подготовить 600 человек на новой учебной линии. Эти предприятия ещё не включены в сохранённую начальную базу; расширение колледжа пока является проектом. Учебная линия требует по смете 500 млн ₽. Регион заявляет 100 млн ₽ своего участия и направил запрос на 400 млн ₽ к проекту федерального бюджета. Эти средства пока существуют лишь в заявке, без решения о выделении и перечисления.\n\nРаботодатели предлагают проводить практическую подготовку на своих производственных линиях, но проект договорённости не распределяет обязанности по оборудованию, наставникам и безопасным условиям. Колледж должен согласовать содержание подготовки и ответственность площадок; реклама вакансий не заменяет такую организацию обучения.\n\nКолледж — государственная образовательная организация субъекта. Практическая подготовка на предприятии оформляется договором с организацией соответствующего профиля и распределением обязанностей, включая безопасность. Короткие программы не заменяют квалификацию СПО; приём осуществляется по установленным правилам. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-64-wastewater-cleaning","old_hash":"362eeec953b144910e442347d5f72973","situation":"В Саратовской области проверка очистных сооружений показала: нормативно очищаются 62% стоков. Приём новых производственных подключений ограничен. Регион подготовил проект обновления оборудования, лабораторного контроля и подготовки персонала. На обновление очистных, контроль и подготовку персонала требуется 800 млн ₽. Регион заявляет свои 160 млн ₽; ещё 640 млн ₽ запрошены при рассмотрении проекта федерального бюджета. Заявка пока не обеспечена решением о выделении и перечислением денег.\n\nОчистные входят в централизованную систему водоотведения; оператор и разрешительные условия определены. Обязательные нормативы и действующие договорные обязанности соблюдаются; новые заявки рассматриваются по установленному порядку технического присоединения, а не произвольному отказу. Расходы, уже обеспеченные бюджетом, не покрываются повторно платой за подключение. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-72-temporary-family-housing","old_hash":"1011f8a0e76b27041d45bfeddc894b87","situation":"В Тюменской области авария инженерных сетей привела к признанию нескольких домов непригодными для проживания. 240 семей размещены временно. Регион подготовил проверенный реестр семей и расчёт приобретения жилья, переезда и сопровождения; расходы на ремонт самих сетей в эту заявку не включены. Жилищная заявка рассчитана на 900 млн ₽: регион заявляет свои 180 млн ₽, а 720 млн ₽ просит предусмотреть в проекте федерального бюджета. Федеральные средства ещё не выделены и не перечислены семьям или иному получателю.\n\nВ реестре отдельно указаны собственники, в отношении которых имеется установленное основание изъятия, и наниматели по соцнайму. При сносе применяется ст. 86, при признании помещения непригодным — применимый порядок ст. 87; временное жильё предоставляется при наличии оснований маневренного фонда. Индивидуальные решения и сроки сохраняются. Все суммы и доли — учебные предложения, а не нормативно установленный размер субсидии."},{"case_key":"budget-region-2026-77-recipient-insolvent","old_hash":"11431ac7d6133b20367eea0d0b931b1f","situation":"В Москве коммерческая организация получила 320 млн ₽ целевой поддержки на создание производственной линии, но не выполнила показатели соглашения. Затем суд открыл конкурсное производство. У публичного органа имеются соглашение, акт проверки и требование о возврате; участник предлагает самостоятельно забрать оборудование со склада, чтобы не ждать других кредиторов. Конкурсный управляющий просит направить документы для учета требования в установленной процедуре. Команда должна защитить публичные средства, различив требование возврата субсидии, обеспеченность требования и порядок действий в деле о банкротстве.\n\nДля учебного расчёта требование возврата субсидии возникло до возбуждения дела о банкротстве, является денежным и не относится к текущим платежам. Оборудование принадлежит должнику; наличие залога не предполагается без доказательств."},{"case_key":"budget-risk-2026-bank_credit","old_hash":"20f3f5b0a5053b987d951e3b17d517a1","situation":"В учебном федеральном бюджете уполномоченный Минфин России законно привлёк рублёвый кредит вымышленного банка «Казначейский партнер». После перечисления кредитных средств у банка отозвана лицензия; заёмщик получил уведомление действующей временной администрации; конкурсный управляющий или ликвидатор ещё не назначен, уступки требования нет. Официальные безналичные реквизиты доступны на сайте Банка России. Остаток основного долга в кредитном договоре составляет 1 200 млн ₽, очередной процентный платеж наступает через пять дней. В чате предлагают списать кредит, поскольку прежние платежные реквизиты перестали работать. Другой участник прислал ссылку на реквизиты, которые размещены только в неофициальном сообщении."},{"case_key":"budget-risk-2026-external","old_hash":"c1e221a6e6283608e31e3a68436e54ad","situation":"После законного внешнего заимствования в учебном федеральном бюджете иностранный кредитор направил график очередного платежа. Обязательство выражено в иностранной валюте, а бюджетные ассигнования и расчеты группы ведутся в рублях. Рублёвый курс валюты долга увеличился на 15 %. Платежный агент сообщает о задержках одного из каналов; договор допускает альтернативного агента после согласования. Часть команды предлагает сохранить старый рублевый эквивалент, поскольку номинал кредита не менялся.\n\nВ учебном случае внешнее заимствование осуществлено законно. Валюта платежа и порядок пересчёта определены договором и обязательными нормами; новый агент применяется только после необходимого согласования и проверки законности."},{"case_key":"budget-risk-2026-ofz_fixed","old_hash":"4fb4d60689bef3b9ea5feac20a127728","situation":"В учебной программе внутренних заимствований федерального бюджета предусмотрено 1 000 млн ₽ чистого привлечения по ОФЗ с постоянным купоном в рассматриваемом периоде. Погашений основного долга и накопленного купонного дохода по этим операциям в периоде нет, размещение ведётся по номиналу. По итогам очередного аукциона размещение и расчёты завершены на 620 млн ₽; оставшиеся заявки не удовлетворены из-за требуемой доходности. Суммы подтверждены учётом казначейства. Через неделю нужно профинансировать обязательства перед получателями бюджетных средств. Казначейство сообщает, что бухгалтерская запись о плановом выпуске не создала денег на счете. Команда должна выбрать способ закрытия кассового разрыва, проверить лимит заимствований и затем уточнить расчет обслуживания."},{"case_key":"budget-risk-2026-ofz_float","old_hash":"35b4063df3530f0fff810a0f3cbe7897","situation":"В принятом учебном федеральном бюджете использован вымышленный выпуск ОФЗ с переменным купоном. В условиях именно этого учебного выпуска ставка равна ключевой ставке на установленную условиями дату определения купона плюс 0,5 процентного пункта. Это не описание формулы какого-либо реального выпуска ОФЗ. После изменения ставки расчетный агент прислал ведомость, в которой к купону добавлена еще и собственная банковская комиссия в 2 процентных пункта, хотя в условиях выпуска такой надбавки нет. Платеж должен пройти через три дня; ведомость и условия займа доступны финансовой команде."},{"case_key":"budget-risk-2026-reserves","old_hash":"eae391d0042fb2f1c147e1cc95e444c4","situation":"В учебном федеральном бюджете предусмотрено использование части средств ФНБ для финансирования дефицита в пределах предусмотренного законом объёма. После опубликования бюджета поступила ведомость активов: часть выбранного резерва вложена в долгосрочные инструменты и не может быть обращена в деньги к сроку ближайших платежей. По предварительным расчётам, недоступная часть составляет 10 000 млн ₽. Общая стоимость фонда в отчетности значительно выше доступного денежного остатка, поэтому участник предлагает просто повторить первоначальный расчет.\n\nДоступность средств ФНБ и сумма 10 млрд заданы только для учебного бюджета, а не как сведения о фактическом ФНБ. Используются только ликвидные активы, разрешённые действующим бюджетным законодательством и установленной процедурой; компетенция федеральных органов, временные особенности действия норм, ограничения заимствований и ранее принятые обязательства сохраняются."}]$gos_payload$::jsonb) AS x(case_key text,old_hash text,situation text);
 IF (SELECT count(*) FROM gos_hint_patch)<>201 OR (SELECT count(DISTINCT case_key) FROM gos_hint_patch)<>201 THEN RAISE EXCEPTION 'Patch coverage'; END IF;
 IF EXISTS(SELECT 1 FROM gos_hint_patch p LEFT JOIN private.authored_event_catalog c USING(case_key) WHERE c.case_key IS NULL OR md5(c.content->>'situation') IS DISTINCT FROM p.old_hash) THEN RAISE EXCEPTION 'Catalogue text changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.event_cases c JOIN private.authored_event_catalog a USING(case_key) JOIN gos_hint_patch p USING(case_key) WHERE c.situation IS DISTINCT FROM a.content->>'situation') THEN RAISE EXCEPTION 'Instance text differs from catalogue'; END IF;
 CREATE TEMP TABLE gos_hint_before ON COMMIT DROP AS SELECT c.id,c.situation,to_jsonb(c)-'situation' unchanged FROM public.event_cases c JOIN gos_hint_patch p USING(case_key);
 INSERT INTO private.event_content_revisions(revision,event_case_id,snapshot) SELECT '2026-11-28-no-predecision-hints',id,jsonb_build_object('situation',situation) FROM gos_hint_before;
 UPDATE private.authored_event_catalog c SET content=jsonb_set(c.content,'{situation}',to_jsonb(p.situation))||jsonb_build_object('pre_decision_editorial_archive',c.content->>'situation') FROM gos_hint_patch p WHERE c.case_key=p.case_key;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>201 THEN RAISE EXCEPTION 'Catalogue update mismatch %',n;END IF;
 UPDATE public.event_cases c SET situation=p.situation FROM gos_hint_patch p WHERE c.case_key=p.case_key;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>(SELECT count(*) FROM gos_hint_before) THEN RAISE EXCEPTION 'Instance update mismatch %',n;END IF;
 IF EXISTS(SELECT 1 FROM gos_hint_before b JOIN public.event_cases c USING(id) WHERE (to_jsonb(c)-'situation') IS DISTINCT FROM b.unchanged) THEN RAISE EXCEPTION 'Unrelated case fields changed';END IF;
 IF EXISTS(SELECT 1 FROM public.event_cases c JOIN private.authored_event_catalog a USING(case_key) WHERE c.situation IS DISTINCT FROM a.content->>'situation') THEN RAISE EXCEPTION 'Catalogue and game text mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM private.authored_event_catalog WHERE (content->>'situation') ~* 'Уточнение учебной правовой модели|Учебные правовые условия\\.|Обязательные условия рассмотрения\\.') THEN RAISE EXCEPTION 'Visible editorial note remains';END IF;
END $migration$;
